INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (1, '1: Greetings & Introductions', 'احوالپرسی و معرفی', 'basics', 1, 'You''re meeting someone new for the first time. Introduce yourself and find out about them.', 'با یه نفر جدید آشنا می‌شید. خودتون رو معرفی کنید و درباره‌شون بیشتر بدونید.', 'Basic greetings: Hallo, Guten Tag, Tschüss', 'احوالپرسی پایه', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (2, '2: Introducing Yourself', 'معرفی خودتان', 'basics', 2, 'You''re greeting different people throughout the day. Practice formal and informal ways to say hello and goodbye.', 'در طول روز با افراد مختلف روبرو می‌شید. روش‌های رسمی و غیررسمی سلام و خداحافظی رو تمرین کنید.', 'Ich bin..., Ich heiße..., Ich komme aus...', 'من هستم... اسم من است... من اهل... هستم', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (3, '3: Numbers 1-20', 'اعداد ۱ تا ۲۰', 'basics', 3, 'A neighbor stops you on the street. Exchange pleasantries and ask how they''re doing.', 'یه همسایه تو خیابون جلوتون رو می‌گیره. احوال‌پرسی کنید و بپرسید حالشون چطوره.', 'Cardinal numbers: eins, zwei, drei... zwanzig', 'اعداد اصلی: یک، دو، سه... بیست', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (4, '4: The Alphabet & Spelling', 'الفبا و املا', 'basics', 4, 'You''re filling out a form and chatting about ages and phone numbers.', 'دارید یه فرم پر می‌کنید و درباره سن و شماره تلفن صحبت می‌کنید.', 'German pronunciation: ä, ö, ü, ß', 'تلفظ آلمانی: ä، ö، ü، ß', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (5, '5: At the Café', 'در کافه', 'basics', 5, 'You''re making plans and need to talk about days of the week, months, and important dates.', 'دارید برنامه‌ریزی می‌کنید و باید درباره روزهای هفته، ماه‌ها و تاریخ‌های مهم صحبت کنید.', 'Polite requests: Ich möchte..., Ich hätte gern...', 'درخواست مؤدبانه: من می‌خواهم...', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (6, '6: Family Members', 'اعضای خانواده', 'basics', 6, 'A new friend asks about your family. Describe who you live with and your family situation.', 'یه دوست جدید درباره خانواده‌تون می‌پرسه. توصیف کنید با چه کسی زندگی می‌کنید.', 'Possessive articles: mein/meine', 'ضمایر ملکی: مال من', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (7, '7: Days & Months', 'روزها و ماه‌ها', 'basics', 7, 'You walk into a cozy café in Berlin. Order a drink and settle in.', 'وارد یه کافه دنج در برلین می‌شید. یه نوشیدنی سفارش بدید و راحت بنشینید.', 'Days of the week, months of the year', 'روزهای هفته، ماه‌های سال', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (8, '8: Colors & Descriptions', 'رنگ‌ها و توصیفات', 'basics', 8, 'You''re lost in an unfamiliar part of town. Stop someone and ask for help.', 'تو یه محله ناآشنا گم شدید. یه نفر رو متوقف کنید و کمک بخواید.', 'Basic adjectives: groß, klein, schön', 'صفات پایه: بزرگ، کوچک، زیبا', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (9, '9: Present Tense Regular Verbs', 'زمان حال افعال باقاعده', 'basics', 9, 'Someone is speaking too fast for you to understand. Ask them to slow down and repeat.', 'یه نفر خیلی سریع صحبت می‌کنه. ازشون بخواید کندتر بگن و تکرار کنن.', 'Conjugation: machen, spielen, lernen', 'صرف فعل: انجام دادن، بازی کردن، یاد گرفتن', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (10, '10: Articles: der, die, das', 'حروف تعریف', 'basics', 10, 'You''re running late for a meeting and something has gone wrong. Apologize and explain.', 'دیر به جلسه رسیدید و یه مشکلی پیش اومده. عذرخواهی کنید و توضیح بدید.', 'Definite and indefinite articles', 'حروف تعریف معین و نامعین', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (11, '11: Food & Groceries', 'غذا و خواربار', 'basics', 11, 'You''ve just met an interesting person at an event. Ask questions to learn more about them.', 'تو یه رویداد با یه نفر جالب آشنا شدید. سوال بپرسید تا بیشتر بشناسیدشون.', 'Ich hätte gern... (I would like...)', 'من می‌خواستم...', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (12, '12: Telling Time', 'ساعت', 'basics', 12, 'You''re describing objects and places around you using colors and basic adjectives.', 'دارید اشیاء و مکان‌های اطرافتون رو با رنگ‌ها و صفات پایه توصیف می‌کنید.', 'Wie spät ist es? Es ist...', 'ساعت چند است؟ ساعت...', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (13, '13: Weather', 'آب و هوا', 'basics', 13, 'You need to find a pharmacy in an unfamiliar neighborhood. Ask a passerby for simple directions.', 'باید یه داروخانه تو محله ناآشنا پیدا کنید. از یه رهگذر مسیر ساده بخواید.', 'Es ist... + weather adjectives', 'هوا... است + صفات آب و هوا', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (14, '14: Hobbies & Free Time', 'سرگرمی‌ها و اوقات فراغت', 'basics', 14, 'You''re looking for the post office in a complex area. Get more detailed directions using landmarks.', 'دارید دنبال اداره پست تو یه منطقه پیچیده می‌گردید. مسیر دقیق‌تر با نشانه‌های محلی بگیرید.', 'Verb + gern: Ich spiele gern...', 'فعل + با میل: من با میل بازی می‌کنم...', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (15, '15: At the Restaurant', 'در رستوران', 'basics', 15, 'You''re at a bus stop and need to find your connection. Ask about departure times and routes.', 'تو ایستگاه اتوبوس هستید و باید مسیر اتصالی رو پیدا کنید. درباره زمان حرکت و مسیر بپرسید.', 'Accusative case basics: Ich nehme den/die/das', 'حالت مفعولی پایه: من ... را می‌گیرم', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (16, '16: Directions', 'مسیریابی', 'survival', 16, 'You''ve just arrived at the airport and need to get to your hotel. Hail a taxi and discuss the fare.', 'تازه وارد فرودگاه شدید و باید به هتل برسید. تاکسی بگیرید و درباره کرایه صحبت کنید.', 'Imperative basics: Gehen Sie..., Biegen Sie ab...', 'امری پایه: بروید...، بپیچید...', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (17, '17: Body Parts & Health', 'اعضای بدن و سلامت', 'survival', 17, 'You''re checking in for your flight. Navigate check-in, baggage drop-off, and finding your gate.', 'دارید برای پروازتون چک‌این می‌کنید. چک‌این، تحویل بار و پیدا کردن گیت رو مدیریت کنید.', 'Mein/Meine... tut/tun weh', '...من درد می‌کند', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (18, '18: Clothes & Shopping', 'لباس و خرید', 'survival', 18, 'You''re chatting with a neighbor about today''s weather and plans for the week ahead.', 'با یه همسایه درباره آب‌وهوای امروز و برنامه‌های هفته پیش رو صحبت می‌کنید.', 'Adjective + noun agreement basics', 'تطابق صفت و اسم پایه', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (19, '19: Home & Rooms', 'خانه و اتاق‌ها', 'survival', 19, 'You''re describing your daily morning routine to a language exchange partner.', 'دارید روتین صبحگاهی روزانه‌تون رو برای شریک تبادل زبانی توصیف می‌کنید.', 'Es gibt... (There is/are...)', '... وجود دارد / هست', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (20, '20: Daily Routine', 'برنامه روزانه', 'survival', 20, 'A friend is visiting your apartment for the first time. Show them around the rooms.', 'یه دوست برای اولین بار به آپارتمانتون می‌آد. خونه رو بهشون نشون بدید.', 'Reflexive verbs basics: sich waschen, sich anziehen', 'افعال انعکاسی پایه: خود را شستن، لباس پوشیدن', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (21, '21: Irregular Verbs: sein & haben', 'افعال بی‌قاعده: بودن و داشتن', 'survival', 21, 'A friend comes over for dinner. Chat about what you''re cooking and whether they''re hungry.', 'یه دوست برای شام می‌آد. درباره آنچه می‌پزید و اینکه گرسنه‌ان صحبت کنید.', 'Conjugation of sein and haben', 'صرف فعل بودن و داشتن', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (22, '22: Negation', 'منفی‌سازی', 'survival', 22, 'You''re trying to schedule a meeting with a colleague. Agree on a time that works for both.', 'دارید سعی می‌کنید با یه همکار قرار ملاقات بگذارید. یه زمان مناسب برای هر دوتون پیدا کنید.', 'nicht vs. kein/keine', 'nicht در مقابل kein/keine', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (23, '23: Yes/No Questions', 'سوالات بله/خیر', 'survival', 23, 'You''re at a party and start chatting with someone you''ve just met. Make some small talk.', 'تو یه مهمانی هستید و با یه نفر که تازه باهاش آشنا شدید صحبت می‌کنید.', 'Verb-first question formation', 'ساختار سوالی با فعل در ابتدا', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (24, '24: W-Questions', 'سوالات با کلمه پرسشی', 'survival', 24, 'You''re getting to know a new colleague over coffee. Talk about hobbies and free time.', 'دارید با یه همکار جدید سر قهوه آشنا می‌شید. درباره سرگرمی‌ها و اوقات فراغت صحبت کنید.', 'Wer, was, wo, wann, warum, wie', 'چه کسی، چه، کجا، کی، چرا، چگونه', 'A1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (25, '25: Personal Pronouns & Cases', 'ضمایر شخصی و حالت‌ها', 'survival', 25, 'It''s Thursday evening. You''re arranging plans with a friend for the weekend.', 'شب پنجشنبه‌ست. دارید با یه دوست برای آخر هفته برنامه‌ریزی می‌کنید.', 'Nominative and Accusative pronouns', 'ضمایر فاعلی و مفعولی', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (26, '26: Perfect Tense Part 1', 'زمان گذشته بخش ۱', 'survival', 26, 'You''re shopping at a weekend market. Ask about prices and pay for your items.', 'دارید تو یه بازار آخر هفته خرید می‌کنید. درباره قیمت‌ها بپرسید و پول بدید.', 'Perfekt with haben (regular verbs)', 'ماضی نقلی با haben (افعال باقاعده)', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (27, '27: Perfect Tense Part 2', 'زمان گذشته بخش ۲', 'survival', 27, 'You''re at the supermarket but can''t find what you need. Ask a staff member for help.', 'تو سوپرمارکت هستید ولی چیزی که نیاز دارید رو پیدا نمی‌کنید. از یه کارمند کمک بخواید.', 'Perfekt with sein (movement/state change)', 'ماضی نقلی با sein (حرکت/تغییر حالت)', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (28, '28: Separable Verbs', 'افعال جداشدنی', 'survival', 28, 'It''s Saturday morning and you''re at the weekly farmers'' market. Buy some fresh bread and pastries.', 'صبح شنبه‌ست و تو بازار هفتگی هستید. کمی نان تازه و شیرینی بخرید.', 'aufstehen, einkaufen, anfangen, mitkommen', 'بلند شدن، خرید کردن، شروع کردن، همراهی کردن', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (29, '29: Modal Verbs Part 1', 'افعال کمکی بخش ۱', 'survival', 29, 'You''re in a clothing store and want to try something on. Talk to the sales assistant.', 'تو یه مغازه لباس هستید و می‌خواید چیزی رو امتحان کنید. با فروشنده صحبت کنید.', 'können, müssen, wollen', 'توانستن، باید، خواستن', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (30, '30: Modal Verbs Part 2', 'افعال کمکی بخش ۲', 'survival', 30, 'You need a new laptop charger. Ask about availability, warranty, and payment options.', 'یه شارژر لپ‌تاپ جدید نیاز دارید. درباره موجودی، گارانتی و روش‌های پرداخت بپرسید.', 'dürfen, sollen, mögen', 'اجازه داشتن، بایستن، دوست داشتن', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (31, '31: The Dative Case', 'حالت مفعولی غیرمستقیم', 'survival', 31, 'You''re in a shop and can''t quite decide between two items. Think out loud and finally choose.', 'تو یه مغازه هستید و بین دو چیز نمی‌تونید تصمیم بگیرید. با خودتون فکر کنید و انتخاب کنید.', 'Dative articles: dem, der, den', 'حروف تعریف مفعول غیرمستقیم: dem, der, den', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (32, '32: Dative Prepositions', 'حروف اضافه با مفعول غیرمستقیم', 'survival', 32, 'It''s Monday morning at the office. Catch up with a colleague about tasks and pending messages.', 'صبح دوشنبه‌ست تو اداره. با یه همکار درباره وظایف و پیام‌های در انتظار صحبت کنید.', 'mit, bei, nach, von, zu, aus, seit', 'با، نزد، بعد از، از، به سوی، از، از زمان', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (33, '33: Two-Way Prepositions', 'حروف اضافه دوگانه', 'survival', 33, 'You need to speak to someone at a company. Call them, navigate the receptionist, and leave a message.', 'باید با یه نفر توی یه شرکت صحبت کنید. زنگ بزنید، از پذیرش عبور کنید و پیام بذارید.', 'Wechselpräpositionen: in, an, auf, über, unter', 'حروف اضافه دوگانه: در، در کنار، روی، بالای، زیر', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (34, '34: Comparatives', 'صفات تفضیلی', 'survival', 34, 'You need to write a professional email to a business contact. Compose a polite, formal message.', 'باید یه ایمیل حرفه‌ای به یه مخاطب تجاری بنویسید. یه پیام مودبانه و رسمی بنویسید.', 'größer als, besser als, mehr als', 'بزرگ‌تر از، بهتر از، بیشتر از', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (35, '35: Superlatives', 'صفات عالی', 'survival', 35, 'You''re at a new restaurant with a friend. Share opinions about the food and atmosphere.', 'با یه دوست تو یه رستوران جدید هستید. نظرتون درباره غذا و فضا رو بگید.', 'am größten, der/die/das beste', 'بزرگ‌ترین، بهترین', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (36, '36: At the Doctor', 'نزد پزشک', 'survival', 36, 'You want to join a German language school. Ask about levels, schedules, and how to enroll.', 'می‌خواید به یه آموزشگاه زبان آلمانی بپیوندید. درباره سطوح، برنامه‌ها و نحوه ثبت‌نام بپرسید.', 'Describing symptoms: Ich habe Schmerzen', 'توصیف علائم: درد دارم', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (37, '37: Bank & Post Office', 'در بانک و پست', 'survival', 37, 'Something has come up and you need to reschedule a work meeting. Handle it professionally.', 'یه اتفاقی افتاده و باید یه جلسه کاری رو جابجا کنید. حرفه‌ای باهاش کنار بیاید.', 'Formal Sie register', 'سطح رسمی با Sie', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (38, '38: Making Appointments', 'گرفتن وقت ملاقات', 'survival', 38, 'You''re not feeling well and a colleague notices. Explain your symptoms and decide what to do.', 'حالتون خوب نیست و یه همکار متوجه می‌شه. علائمتون رو توضیح بدید و تصمیم بگیرید چیکار کنید.', 'Future with werden + time expressions', 'آینده با werden + عبارات زمانی', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (39, '39: Travel & Transportation', 'سفر و حمل و نقل', 'survival', 39, 'You have an appointment with your GP. Describe your symptoms and receive medical advice.', 'نوبت پزشک عمومی دارید. علائمتون رو توصیف کنید و توصیه پزشکی بگیرید.', 'Prepositions of direction: nach, in, an', 'حروف اضافه جهت: به، در، کنار', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (40, '40: Hotel & Accommodation', 'هتل و اقامت', 'survival', 40, 'You have a cold and need something from the pharmacy. Describe symptoms and ask for a remedy.', 'سرما خوردید و از داروخانه چیزی نیاز دارید. علائم رو بگید و داروی مناسب بخواید.', 'Ordinal numbers: erste, zweite, dritte', 'اعداد ترتیبی: اول، دوم، سوم', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (41, '41: Reflexive Verbs', 'افعال انعکاسی', 'survival', 41, 'Your tooth has been hurting for two days. Call the dentist, describe the pain, and make an appointment.', 'دندونتون دو روزه درد می‌کنه. به دندونپزشک زنگ بزنید، درد رو توصیف کنید و نوبت بگیرید.', 'sich freuen, sich erinnern, sich interessieren', 'خوشحال شدن، به یاد آوردن، علاقه‌مند بودن', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (42, '42: Subordinate Clauses: weil', 'جملات وابسته: زیرا', 'survival', 42, 'You''ve joined a gym and are chatting with another member about fitness routines and goals.', 'به باشگاه پیوستید و با یه عضو دیگه درباره برنامه ورزشی و اهداف صحبت می‌کنید.', 'Verb-final position with weil', 'فعل در انتهای جمله با weil', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (43, '43: Subordinate Clauses: dass', 'جملات وابسته: که', 'survival', 43, 'You''re at a restaurant with dietary restrictions. Make sure the waiter fully understands your needs.', 'تو رستوران هستید و محدودیت غذایی دارید. مطمئن بشید که گارسون کاملاً نیازهاتون رو می‌فهمه.', 'Verb-final position with dass', 'فعل در انتهای جمله با dass', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (44, '44: Subordinate Clauses: wenn/als', 'جملات وابسته: وقتی', 'survival', 44, 'You''ve booked a table at a nice restaurant. Order food, ask for the chef''s recommendations, and pay.', 'میز تو یه رستوران خوب رزرو کردید. غذا سفارش بدید، پیشنهاد سرآشپز رو بپرسید و حساب کنید.', 'wenn (repeated) vs. als (one-time past)', 'wenn (تکراری) در مقابل als (یکبار در گذشته)', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (45, '45: Adjective Declension: Nominative', 'صرف صفت: فاعلی', 'survival', 45, 'You''re settling in at a café to work for a couple of hours. Order, ask about Wi-Fi, and get comfortable.', 'دارید تو یه کافه مستقر می‌شید تا چند ساعت کار کنید. سفارش بدید، درباره وای‌فای بپرسید و راحت باشید.', 'der große Mann, eine kleine Frau', 'مرد بزرگ، یک زن کوچک', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (46, '46: Adjective Declension: Acc/Dat', 'صرف صفت: مفعولی', 'scenarios', 46, 'You''ve been invited to a colleague''s birthday party. Bring a gift and join in the celebrations.', 'به مهمانی تولد یه همکار دعوت شدید. یه هدیه بیارید و توی جشن شرکت کنید.', 'den großen Mann, mit dem kleinen Kind', 'مرد بزرگ را، با بچه کوچک', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (47, '47: Work & Professions', 'کار و حرفه‌ها', 'scenarios', 47, 'You''re buying cinema tickets for tonight''s showing. Choose a film and get the best available seats.', 'دارید بلیت سینما برای نمایش امشب می‌خرید. یه فیلم انتخاب کنید و بهترین صندلی‌های موجود رو بگیرید.', 'als + profession: Ich arbeite als...', 'به عنوان + شغل: من کار می‌کنم به عنوان...', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (48, '48: Education & School', 'آموزش و مدرسه', 'scenarios', 48, 'You''re at a social gathering and meet someone new. Pay compliments and strike up a conversation.', 'تو یه گردهمایی اجتماعی هستید و با یه نفر جدید آشنا می‌شید. تعریف کنید و مکالمه شروع کنید.', 'um...zu + infinitive (purpose clauses)', 'برای... + مصدر (جملات هدف)', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (49, '49: Technology & Internet', 'فناوری و اینترنت', 'scenarios', 49, 'It''s Friday afternoon. Chat with a friend about what you''re both doing this weekend.', 'بعدازظهر جمعه‌ست. با یه دوست درباره برنامه‌های آخر هفته‌تون صحبت کنید.', 'Compound nouns: Computerspiel, Handynummer', 'اسامی مرکب: بازی کامپیوتری، شماره موبایل', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (50, '50: Coordinating Conjunctions', 'حروف ربط هم‌پایه', 'scenarios', 50, 'You''re calling a hotel in Munich to book a room for a business trip next week.', 'دارید به یه هتل در مونیخ زنگ می‌زنید تا اتاقی برای سفر کاری هفته آینده رزرو کنید.', 'und, aber, oder, denn, sondern', 'و، اما، یا، زیرا، بلکه', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (51, '51: Simple Past: Präteritum', 'گذشته ساده', 'scenarios', 51, 'You need to open a current account at a German bank. Ask all the right questions and fill in the forms.', 'باید یه حساب جاری در یه بانک آلمانی باز کنید. سوالات لازم رو بپرسید و فرم‌ها رو پر کنید.', 'war, hatte, konnte, musste', 'بود، داشت، توانست، باید', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (52, '52: Passive Voice: Present', 'مجهول: حال', 'scenarios', 52, 'You need to send a parcel to Iran. Weigh it, fill in the customs form, and choose a delivery option.', 'باید یه بسته به ایران بفرستید. وزن کنید، فرم گمرک پر کنید و گزینه ارسال رو انتخاب کنید.', 'werden + Partizip II', 'شدن + اسم مفعول', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (53, '53: Relative Clauses', 'جملات موصولی', 'scenarios', 53, 'You''re at a car rental counter at the airport. Choose a vehicle class and sort out insurance.', 'تو باجه اجاره خودرو در فرودگاه هستید. کلاس خودرو رو انتخاب کنید و بیمه رو مرتب کنید.', 'der/die/das as relative pronouns', 'که/کسی که به عنوان ضمیر موصولی', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (54, '54: The Genitive Case', 'حالت اضافی', 'scenarios', 54, 'You want to join a language school. Ask about the placement test, class sizes, timetable, and fees.', 'می‌خواید به یه آموزشگاه زبان بپیوندید. درباره آزمون تعیین سطح، اندازه کلاس، برنامه و هزینه بپرسید.', 'des/der + noun, wegen, trotz', 'ملکی با des/der، به خاطر، با وجود', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (55, '55: Indirect Questions', 'سوالات غیرمستقیم', 'scenarios', 55, 'A busy day of mixed situations. You''ll revisit key phrases and structures from the first 54 lessons.', 'یه روز پر از موقعیت‌های مختلف. عبارات و ساختارهای کلیدی از ۵۴ درس اول رو مرور می‌کنید.', 'ob, wann, wie, wo in indirect speech', 'آیا، کی، چگونه، کجا در نقل‌قول غیرمستقیم', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (56, '56: Environment & Nature', 'محیط زیست و طبیعت', 'scenarios', 56, 'You''ve found a flat you like online. Visit the apartment and negotiate the rental terms with the landlord.', 'یه آپارتمان آنلاین پیدا کردید. از آپارتمان بازدید کنید و با صاحبخانه درباره شرایط اجاره مذاکره کنید.', 'man + passive alternatives', 'ساختار man + جایگزین مجهول', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (57, '57: Media & News', 'رسانه و اخبار', 'scenarios', 57, 'Your internet has gone down and you''ve been without connection for hours. Call the provider for help.', 'اینترنتتون قطع شده و چند ساعته بدون اتصال هستید. با ارائه‌دهنده تماس بگیرید.', 'Reported speech basics: Er sagt, dass...', 'نقل‌قول پایه: او می‌گوید که...', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (58, '58: Health & Lifestyle', 'سلامت و سبک زندگی', 'scenarios', 58, 'At the station you realise you''ve missed your train and your flight is delayed. Get help from the information desk.', 'تو ایستگاه متوجه می‌شید قطارتون رو از دست دادید و پروازتون تأخیر داره. از باجه اطلاعات کمک بگیرید.', 'Infinitive clauses: ohne...zu, statt...zu', 'جملات مصدری: بدون اینکه...، به جای اینکه...', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (59, '59: Expressing Opinions', 'بیان نظر', 'scenarios', 59, 'You have a job interview at a German company. Answer questions about your experience and motivation.', 'مصاحبه شغلی در یه شرکت آلمانی دارید. به سوالات درباره تجربه و انگیزه‌تون جواب بدید.', 'Ich finde/denke/meine, dass...', 'فکر می‌کنم/به نظرم، که...', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (60, '60: Cultural Differences', 'تفاوت‌های فرهنگی', 'scenarios', 60, 'Your wallet has been stolen while sightseeing. Report the theft to the police and contact your embassy.', 'موقع گردشگری کیف پولتون دزدیده شده. دزدی رو به پلیس گزارش بدید و با سفارت‌خانه تماس بگیرید.', 'Temporal clauses: bevor, nachdem, während', 'جملات زمانی: قبل از، بعد از، در حین', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (61, '61: Konjunktiv II: würde + Infinitiv', 'وجه التزامی: فرضی', 'scenarios', 61, 'Talk about your hobbies and personal interests with a German friend. Share what you enjoy doing in your spare time.', 'درباره سرگرمی‌ها و علایق شخصیتون با یه دوست آلمانی صحبت کنید. بگید در اوقات فراغت چه کار دوست دارید انجام بدید.', 'Hypothetical situations with würde', 'حالت‌های فرضی با würde', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (62, '62: Konjunktiv II: hätte/wäre', 'وجه التزامی: داشتن/بودن', 'scenarios', 62, 'Compare life today with the past. Talk about how technology, travel, and daily habits have changed over the decades.', 'زندگی امروز رو با گذشته مقایسه کنید. درباره اینکه چطور فناوری، سفر و عادات روزانه در طول دهه‌ها تغییر کرده صحبت کنید.', 'hätte, wäre, könnte, müsste', 'داشتم، بودم، می‌توانستم، مجبور بودم', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (63, '63: Passive Voice: Past', 'مجهول: گذشته', 'scenarios', 63, 'Ask a friend for advice on a personal problem. Learn to give and receive suggestions using polite conditional forms.', 'از یک دوست درباره یک مشکل شخصی مشورت بخواهید. یاد بگیرید با استفاده از اشکال شرطی مودبانه پیشنهاد بدید و دریافت کنید.', 'wurde + Partizip II, ist...worden', 'شد + اسم مفعول', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (64, '64: N-Declension', 'تصریف نون', 'scenarios', 64, 'Discuss a topic with a German speaker and practice expressing whether you agree or disagree, and how to handle differing opinions politely.', 'درباره یک موضوع با یک آلمانی‌زبان بحث کنید و تمرین کنید که موافقت یا مخالفت خود را بیان کنید و با نظرات متفاوت محترمانه برخورد کنید.', 'den Studenten, dem Kollegen, des Herrn', 'دانشجو را، به همکار، آقای', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (65, '65: Double Infinitive', 'مصدر دوگانه', 'scenarios', 65, 'Discuss current events and the news with a German speaker. Share your sources, opinions, and reactions to what''s happening in the world.', 'رویدادهای جاری و اخبار را با یک آلمانی‌زبان بحث کنید. منابع، نظرات و واکنش‌های خود را نسبت به اتفاقاتی که در دنیا می‌افتد به اشتراک بگذارید.', 'hat kommen können, hat machen wollen', 'توانست بیاید، خواست انجام دهد', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (66, '66: Advanced Adjective Declension', 'صرف پیشرفته صفت', 'scenarios', 66, 'Describe people''s personalities and character traits to a German friend. Talk about strengths, weaknesses, and what you value in others.', 'شخصیت و خصوصیات اخلاقی افراد را برای یک دوست آلمانی توصیف کنید. درباره نقاط قوت، ضعف‌ها و آنچه در دیگران ارزش می‌گذارید صحبت کنید.', 'Adjectives without articles', 'صفات بدون حرف تعریف', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (67, '67: Formal Letter Writing', 'نامه‌نگاری رسمی', 'scenarios', 67, 'Navigate German bureaucracy — visit the Bürgeramt, apply for permits, and deal with official paperwork and government letters.', 'با بروکراسی آلمان کنار بیایید — به اداره امور شهروندان بروید، برای مجوزها درخواست دهید و با کاغذبازی و نامه‌های رسمی سروکار داشته باشید.', 'Formal register: Sehr geehrte/r', 'سطح رسمی: محترم', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (68, '68: Job Interview', 'مصاحبه شغلی', 'scenarios', 68, 'Handle professional apologies in German — take responsibility for mistakes, address client complaints, and promise corrective action.', 'در آلمان به صورت حرفه‌ای عذرخواهی کنید — مسئولیت اشتباهات را بپذیرید، به شکایات مشتریان رسیدگی کنید و اقدام اصلاحی قول دهید.', 'Complex self-presentation', 'معرفی پیچیده خود', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (69, '69: Renting an Apartment', 'اجاره آپارتمان', 'scenarios', 69, 'Discuss your future goals and ambitions with a German friend. Talk about career plans, personal dreams, and New Year''s resolutions.', 'اهداف و بلندپروازی‌های آینده‌تان را با یک دوست آلمانی بحث کنید. درباره برنامه‌های شغلی، رویاهای شخصی و تصمیمات سال جدید صحبت کنید.', 'Conditional clauses: Wenn ich...würde', 'جملات شرطی: اگر من...', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (70, '70: Social Issues', 'مسائل اجتماعی', 'scenarios', 70, 'Discuss your favourite films, books and TV shows with a German friend. Share opinions, make recommendations, and plan a cinema trip.', 'فیلم‌ها، کتاب‌ها و سریال‌های مورد علاقه‌تان را با یک دوست آلمانی بحث کنید. نظر بدهید، پیشنهاد دهید و برای رفتن به سینما برنامه‌ریزی کنید.', 'Concessive clauses: obwohl, trotzdem', 'جملات تقابلی: با وجود اینکه، با این حال', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (71, '71: Weekend Plans', 'برنامه آخر هفته', 'scenarios', 71, '', '', 'Future with werden; time expressions', 'آینده با werden؛ عبارات زمانی', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (72, '72: Cooking Together', 'آشپزی با هم', 'scenarios', 72, '', '', 'Imperative; food vocabulary', 'امری؛ واژگان غذا', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (73, '73: At the Gym', 'در باشگاه ورزشی', 'scenarios', 73, '', '', 'Modal verbs review; body and fitness', 'مرور افعال کمکی؛ بدن و تناسب اندام', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (74, '74: Visiting Friends', 'دیدار دوستان', 'scenarios', 74, '', '', 'Perfekt with sein; social vocabulary', 'گذشته با sein؛ واژگان اجتماعی', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (75, '75: Moving to a New City', 'نقل مکان به شهر جدید', 'scenarios', 75, '', '', 'weil/dass clauses; city vocabulary', 'جملات با weil/dass؛ واژگان شهری', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (76, '76: Public Transport Problems', 'مشکلات حمل و نقل عمومی', 'advanced', 76, '', '', 'weil clauses; transport vocabulary', 'جملات با weil؛ واژگان حمل و نقل', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (77, '77: At the Market', 'در بازار', 'advanced', 77, '', '', 'Quantities and measurements; polite requests', 'مقادیر و اندازه‌ها؛ درخواست مؤدبانه', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (78, '78: Birthday Party Planning', 'برنامه‌ریزی جشن تولد', 'advanced', 78, '', '', 'Conditional wenn; party vocabulary', 'شرطی با wenn؛ واژگان مهمانی', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (79, '79: Job Search', 'جستجوی کار', 'advanced', 79, '', '', 'Perfekt tense review; work vocabulary', 'مرور زمان گذشته؛ واژگان کاری', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (80, '80: Describing Your Home', 'توصیف خانه', 'advanced', 80, '', '', 'es gibt; furniture and room vocabulary', 'es gibt؛ واژگان مبلمان و اتاق', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (81, '81: Childhood Memories', 'خاطرات کودکی', 'advanced', 81, '', '', 'Präteritum (simple past); als clauses', 'گذشته ساده؛ جملات با als', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (82, '82: Online Shopping', 'خرید آنلاین', 'advanced', 82, '', '', 'zu + infinitive; shopping vocabulary', 'zu + مصدر؛ واژگان خرید', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (83, '83: At the Hairdresser', 'در آرایشگاه', 'advanced', 83, '', '', 'Adjective endings; appearance vocabulary', 'پایانه‌های صفت؛ واژگان ظاهر', 'A2');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (84, '84: Talking About Movies', 'صحبت درباره فیلم', 'advanced', 84, '', '', 'dass clauses; opinion expressions', 'جملات با dass؛ بیان نظر', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (85, '85: Recycling and Environment', 'بازیافت و محیط زیست', 'advanced', 85, '', '', 'man + verb; environment vocabulary', 'man + فعل؛ واژگان محیط زیست', 'B1');
INSERT INTO lessons (day, title, title_fa, "group", sort_order, description, description_fa, grammar_focus, grammar_focus_fa, difficulty) VALUES (86, '86: Learning a Language', 'یادگیری یک زبان', 'advanced', 86, '', '', 'gern/lieber/am liebsten; learning vocabulary', 'gern/lieber/am liebsten؛ واژگان یادگیری', 'A2');
