INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 1, 'A1', 0, 'received', 'Hallo! Guten Morgen.', NULL, 'Hello! Good morning.', 'سلام! صبح بخیر.', NULL, NULL FROM lessons WHERE day = 1;
