INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 3, 'A1', 0, 'received', 'Guten Tag! Wie viel kostet der Kaffee?', NULL, 'Good day! How much does the coffee cost?', 'روز بخیر! قهوه چقدر است؟', NULL, NULL FROM lessons WHERE day = 3;
