INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 19, 'A1', 0, 'received', 'Wie ist deine Wohnung?', NULL, 'How is your apartment?', 'آپارتمانت چطور است؟', NULL, NULL FROM lessons WHERE day = 19;
