INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 38, 'A2', 8, 'received', 'Wie ist Ihr Name, bitte?', NULL, 'What is your name, please?', 'اسمتان چیست، لطفا؟', NULL, NULL FROM lessons WHERE day = 38;
