INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 0, 'received', 'Wofür interessierst du dich?', NULL, 'What are you interested in?', 'به چه چیزی علاقه‌مندی؟', NULL, NULL FROM lessons WHERE day = 41;
