INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 2, 'received', 'Erinnerst du dich an unseren ersten Deutschkurs?', NULL, 'Do you remember our first German class?', 'کلاس اول آلمانی‌مان یادت هست؟', NULL, NULL FROM lessons WHERE day = 41;
