INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 4, 'received', 'Freust du dich auf den Urlaub?', NULL, 'Are you looking forward to the vacation?', 'از تعطیلات ذوق‌زده‌ای؟', NULL, NULL FROM lessons WHERE day = 41;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 5, 'sent', NULL, 'Ja, ich freue mich sehr auf den Urlaub in Spanien.', 'Yes, I am very excited about the vacation in Spain.', 'بله، خیلی از تعطیلات در اسپانیا ذوق‌زده‌ام.', NULL, NULL FROM lessons WHERE day = 41;
