INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 8, 'received', 'Hast du dich für den Kurs angemeldet?', NULL, 'Have you registered for the course?', 'برای کلاس ثبت‌نام کرده‌ای؟', NULL, NULL FROM lessons WHERE day = 41;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 9, 'sent', NULL, 'Ja, ich habe mich gestern online angemeldet.', 'Yes, I registered online yesterday.', 'بله، دیروز آنلاین ثبت‌نام کردم.', NULL, NULL FROM lessons WHERE day = 41;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 10, 'received', 'Wir treffen uns morgen um drei vor dem Kino.', NULL, 'We are meeting tomorrow at three in front of the cinema.', 'فردا ساعت سه جلوی سینما قرار می‌گذاریم.', NULL, NULL FROM lessons WHERE day = 41;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 41, 'A2', 11, 'sent', NULL, 'Gut, ich freue mich darauf! Bis morgen!', 'Good, I am looking forward to it! See you tomorrow!', 'خوب، منتظرش هستم! تا فردا!', NULL, NULL FROM lessons WHERE day = 41;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 0, 'received', 'Warum lernst du Deutsch?', NULL, 'Why are you learning German?', 'چرا آلمانی یاد می‌گیری؟', NULL, NULL FROM lessons WHERE day = 42;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 1, 'sent', NULL, 'Ich lerne Deutsch, weil ich in Deutschland studieren möchte.', 'I learn German because I want to study in Germany.', 'آلمانی یاد می‌گیرم چون می‌خواهم در آلمان تحصیل کنم.', NULL, NULL FROM lessons WHERE day = 42;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 2, 'received', 'Warum bist du müde?', NULL, 'Why are you tired?', 'چرا خسته‌ای؟', NULL, NULL FROM lessons WHERE day = 42;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 3, 'sent', NULL, 'Ich bin müde, weil ich gestern spät ins Bett gegangen bin.', 'I am tired because I went to bed late yesterday.', 'خسته‌ام چون دیشب دیر خوابیدم.', NULL, NULL FROM lessons WHERE day = 42;
