INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 5, 'sent', NULL, 'Er fährt nicht mit dem Auto, weil er keinen Führerschein hat.', 'He doesn''t drive because he doesn''t have a driver''s license.', 'با ماشین نمی‌رود چون گواهینامه ندارد.', NULL, NULL FROM lessons WHERE day = 42;
