INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 7, 'sent', NULL, 'Ich esse kein Fleisch, weil ich Vegetarier bin.', 'I don''t eat meat because I am a vegetarian.', 'گوشت نمی‌خورم چون گیاه‌خوار هستم.', NULL, NULL FROM lessons WHERE day = 42;
