INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 9, 'sent', NULL, 'Ich bleibe zu Hause, weil ich krank bin.', 'I am staying home because I am sick.', 'خانه می‌مانم چون مریض هستم.', NULL, NULL FROM lessons WHERE day = 42;
