INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 42, 'A2', 11, 'sent', NULL, 'Ich mag Berlin, weil die Stadt sehr lebendig und multikulturell ist.', 'I like Berlin because the city is very lively and multicultural.', 'برلین را دوست دارم چون شهر خیلی پرانرژی و چندفرهنگی است.', NULL, NULL FROM lessons WHERE day = 42;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 0, 'received', 'Was denkst du über den neuen Lehrer?', NULL, 'What do you think about the new teacher?', 'درباره معلم جدید چه فکر می‌کنی؟', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 1, 'sent', NULL, 'Ich denke, dass er sehr gut erklärt.', 'I think that he explains very well.', 'فکر می‌کنم که خیلی خوب توضیح می‌دهد.', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 2, 'received', 'Weißt du, dass morgen ein Feiertag ist?', NULL, 'Do you know that tomorrow is a holiday?', 'می‌دانی فردا تعطیل است؟', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 3, 'sent', NULL, 'Nein, das wusste ich nicht! Das ist ja toll!', 'No, I didn''t know that! That''s great!', 'نه، نمی‌دانستم! عالیه!', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 4, 'received', 'Glaubst du, dass es morgen regnet?', NULL, 'Do you think that it will rain tomorrow?', 'فکر می‌کنی فردا باران می‌بارد؟', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 5, 'sent', NULL, 'Ja, ich glaube, dass es morgen regnet.', 'Yes, I think that it will rain tomorrow.', 'بله، فکر می‌کنم فردا باران می‌بارد.', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'A2', 6, 'received', 'Es ist wichtig, dass du pünktlich kommst.', NULL, 'It is important that you come on time.', 'مهم است که سر وقت بیایی.', NULL, NULL FROM lessons WHERE day = 43;
