INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'B1', 10, 'received', 'Man sagt, dass Deutsch eine schwere Sprache ist.', NULL, 'They say that German is a difficult language.', 'می‌گویند که آلمانی زبان سختی است.', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 43, 'B1', 11, 'sent', NULL, 'Ich finde, dass Deutsch nicht so schwer ist, wenn man übt.', 'I find that German is not so hard when you practice.', 'به نظرم آلمانی اگر تمرین کنی آنقدر سخت نیست.', NULL, NULL FROM lessons WHERE day = 43;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'A2', 0, 'received', 'Was machst du, wenn es regnet?', NULL, 'What do you do when it rains?', 'وقتی باران می‌بارد چه کار می‌کنی؟', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'A2', 1, 'sent', NULL, 'Wenn es regnet, bleibe ich zu Hause und lese ein Buch.', 'When it rains, I stay home and read a book.', 'وقتی باران می‌بارد، خانه می‌مانم و کتاب می‌خوانم.', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'B1', 2, 'received', 'Was hast du gemacht, als du ein Kind warst?', NULL, 'What did you do when you were a child?', 'وقتی بچه بودی چه کار می‌کردی؟', NULL, NULL FROM lessons WHERE day = 44;
