INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'A2', 4, 'received', 'Rufst du mich an, wenn du ankommst?', NULL, 'Will you call me when you arrive?', 'وقتی رسیدی بهم زنگ می‌زنی؟', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'A2', 5, 'sent', NULL, 'Ja, ich rufe dich an, wenn ich da bin.', 'Yes, I will call you when I am there.', 'بله، وقتی رسیدم بهت زنگ می‌زنم.', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'B1', 6, 'received', 'Was ist passiert, als du nach Deutschland gekommen bist?', NULL, 'What happened when you came to Germany?', 'وقتی به آلمان آمدی چه اتفاقی افتاد؟', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'B1', 7, 'sent', NULL, 'Als ich nach Deutschland kam, konnte ich kein Wort Deutsch.', 'When I came to Germany, I couldn''t speak a word of German.', 'وقتی به آلمان آمدم، یک کلمه آلمانی بلد نبودم.', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'A2', 8, 'received', 'Wenn du Zeit hast, können wir zusammen kochen.', NULL, 'If you have time, we can cook together.', 'اگر وقت داری، می‌توانیم با هم آشپزی کنیم.', NULL, NULL FROM lessons WHERE day = 44;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 44, 'A2', 9, 'sent', NULL, 'Ja gern! Wenn ich morgen frei habe, komme ich vorbei.', 'Yes, gladly! If I am free tomorrow, I will come by.', 'بله با کمال میل! اگر فردا آزاد باشم، سر می‌زنم.', NULL, NULL FROM lessons WHERE day = 44;
