INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 45, 'A2', 6, 'received', 'Ist das ein deutsches Auto?', NULL, 'Is that a German car?', 'آن ماشین آلمانی است؟', NULL, NULL FROM lessons WHERE day = 45;
