INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 46, 'B1', 7, 'sent', NULL, 'Ja, er wohnt in dem gelben Haus neben der kleinen Bäckerei.', 'Yes, he lives in the yellow house next to the small bakery.', 'بله، در خانه زرد کنار نانوایی کوچک زندگی می‌کند.', NULL, NULL FROM lessons WHERE day = 46;
