INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 46, 'B1', 9, 'sent', NULL, 'Gern! Der frische Kuchen schmeckt am besten.', 'Gladly! The fresh cake tastes the best.', 'با کمال میل! کیک تازه بهترین مزه را دارد.', NULL, NULL FROM lessons WHERE day = 46;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 47, 'A2', 0, 'received', 'Was sind Sie von Beruf?', NULL, 'What is your profession?', 'شغل شما چیست؟', NULL, NULL FROM lessons WHERE day = 47;
