INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 47, 'A2', 3, 'sent', NULL, 'Ich arbeite seit zwei Jahren bei dieser Firma.', 'I have been working at this company for two years.', 'دو سال است که در این شرکت کار می‌کنم.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 47, 'A2', 4, 'received', 'Gefällt Ihnen die Arbeit?', NULL, 'Do you like the work?', 'از کارتان راضی هستید؟', NULL, NULL FROM lessons WHERE day = 47;
