INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 47, 'A2', 6, 'received', 'Was hat Ihr Vater beruflich gemacht?', NULL, 'What did your father do for work?', 'پدرتان چه شغلی داشت؟', NULL, NULL FROM lessons WHERE day = 47;
