INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 47, 'B1', 9, 'sent', NULL, 'Ich möchte als Ingenieur in der Automobilindustrie arbeiten.', 'I want to work as an engineer in the automotive industry.', 'می‌خواهم به عنوان مهندس در صنعت خودرو کار کنم.', NULL, NULL FROM lessons WHERE day = 47;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'A2', 0, 'received', 'Warum bist du nach Deutschland gekommen?', NULL, 'Why did you come to Germany?', 'چرا به آلمان آمدی؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'B1', 1, 'sent', NULL, 'Ich bin nach Deutschland gekommen, um Medizin zu studieren.', 'I came to Germany to study medicine.', 'به آلمان آمدم تا پزشکی بخوانم.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'B1', 2, 'received', 'Wie ist das Bildungssystem in Deutschland?', NULL, 'How is the education system in Germany?', 'سیستم آموزشی آلمان چطور است؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'B1', 3, 'sent', NULL, 'Es ist anders als im Iran. Man muss viel selbstständig lernen.', 'It is different from Iran. You have to study a lot independently.', 'فرق دارد با ایران. باید خیلی مستقل درس بخوانی.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'B1', 4, 'received', 'Was brauchst du, um an der Universität zu studieren?', NULL, 'What do you need to study at the university?', 'برای تحصیل در دانشگاه چه لازم داری؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'B1', 5, 'sent', NULL, 'Man braucht das Abitur oder eine anerkannte Qualifikation, um zu studieren.', 'You need the Abitur or a recognized qualification to study.', 'برای تحصیل به دیپلم آلمانی یا مدرک معادل نیاز داری.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'A2', 6, 'received', 'Lernst du auch zu Hause?', NULL, 'Do you also study at home?', 'خانه هم درس می‌خوانی؟', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'B1', 7, 'sent', NULL, 'Ja, ich gehe jeden Tag in die Bibliothek, um in Ruhe zu lernen.', 'Yes, I go to the library every day to study in peace.', 'بله، هر روز کتابخانه می‌روم تا در آرامش درس بخوانم.', NULL, NULL FROM lessons WHERE day = 48;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 48, 'A2', 8, 'received', 'Hast du schon alle Prüfungen bestanden?', NULL, 'Have you already passed all exams?', 'همه امتحان‌ها را قبول شده‌ای؟', NULL, NULL FROM lessons WHERE day = 48;
