INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 49, 'A2', 0, 'received', 'Benutzt du oft das Internet?', NULL, 'Do you use the internet often?', 'زیاد از اینترنت استفاده می‌کنی؟', NULL, NULL FROM lessons WHERE day = 49;
