INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 49, 'B1', 4, 'received', 'Hast du eine Lieblingsapp auf deinem Smartphone?', NULL, 'Do you have a favorite app on your smartphone?', 'اپلیکیشن مورد علاقه‌ای روی گوشیت داری؟', NULL, NULL FROM lessons WHERE day = 49;
