INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 49, 'A2', 6, 'received', 'Spielst du Computerspiele?', NULL, 'Do you play computer games?', 'بازی کامپیوتری بازی می‌کنی؟', NULL, NULL FROM lessons WHERE day = 49;
