INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 49, 'B1', 8, 'received', 'Wie schützt du deine Daten im Internet?', NULL, 'How do you protect your data on the internet?', 'چطور اطلاعاتت را در اینترنت محافظت می‌کنی؟', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 49, 'B1', 9, 'sent', NULL, 'Ich benutze starke Passwörter und aktualisiere regelmäßig meine Software.', 'I use strong passwords and regularly update my software.', 'رمزهای قوی استفاده می‌کنم و مرتب نرم‌افزارم را بروزرسانی می‌کنم.', NULL, NULL FROM lessons WHERE day = 49;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 0, 'received', 'Möchtest du Tee oder Kaffee?', NULL, 'Would you like tea or coffee?', 'چای می‌خواهی یا قهوه؟', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'B1', 1, 'sent', NULL, 'Ich möchte Tee, denn Kaffee trinke ich nicht so gern.', 'I would like tea, because I don''t like coffee that much.', 'چای می‌خواهم، چون قهوه زیاد دوست ندارم.', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 2, 'received', 'Gehst du heute ins Fitnessstudio?', NULL, 'Are you going to the gym today?', 'امروز باشگاه می‌روی؟', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 3, 'sent', NULL, 'Ich möchte gehen, aber ich habe keine Zeit.', 'I would like to go, but I don''t have time.', 'دلم می‌خواهد بروم اما وقت ندارم.', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 4, 'received', 'Ist er krank?', NULL, 'Is he sick?', 'مریض است؟', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'B1', 5, 'sent', NULL, 'Er ist nicht krank, sondern er ist nur müde.', 'He is not sick, but rather he is just tired.', 'مریض نیست بلکه فقط خسته است.', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 6, 'received', 'Was machst du heute?', NULL, 'What are you doing today?', 'امروز چه کار می‌کنی؟', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 7, 'sent', NULL, 'Ich gehe einkaufen und dann besuche ich meine Freunde.', 'I am going shopping and then I am visiting my friends.', 'خرید می‌روم و بعد به دوستانم سر می‌زنم.', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'A2', 8, 'received', 'Liest du gern Romane?', NULL, 'Do you like reading novels?', 'رمان خواندن دوست داری؟', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 50, 'B1', 9, 'sent', NULL, 'Ja, ich lese gern Romane, aber ich habe leider wenig Zeit dafür.', 'Yes, I like reading novels, but unfortunately I have little time for it.', 'بله، رمان خواندن دوست دارم ولی متاسفانه وقت کمی دارم.', NULL, NULL FROM lessons WHERE day = 50;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 0, 'received', 'Wie war dein Wochenende?', NULL, 'How was your weekend?', 'آخر هفته‌ات چطور بود؟', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 1, 'sent', NULL, 'Es war sehr schön. Ich war am Samstag im Museum.', 'It was very nice. I was at the museum on Saturday.', 'خیلی خوب بود. شنبه در موزه بودم.', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 2, 'received', 'Hattest du gestern Unterricht?', NULL, 'Did you have class yesterday?', 'دیروز کلاس داشتی؟', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 3, 'sent', NULL, 'Nein, ich hatte gestern frei. Es gab keinen Unterricht.', 'No, I had the day off yesterday. There was no class.', 'نه، دیروز تعطیل بودم. کلاسی نبود.', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 4, 'received', 'Konntest du als Kind schwimmen?', NULL, 'Could you swim as a child?', 'وقتی بچه بودی شنا بلد بودی؟', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 5, 'sent', NULL, 'Nein, ich konnte erst mit zehn Jahren schwimmen.', 'No, I could only swim from the age of ten.', 'نه، از ده سالگی تازه شنا یاد گرفتم.', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 6, 'received', 'Es war einmal ein König, der in einem großen Schloss lebte.', NULL, 'Once upon a time there was a king who lived in a big castle.', 'یکی بود یکی نبود، پادشاهی بود که در قلعه بزرگی زندگی می‌کرد.', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 7, 'sent', NULL, 'Die Geschichte klingt interessant! Was passierte dann?', 'The story sounds interesting! What happened then?', 'داستان جالب به نظر می‌رسد! بعد چه شد؟', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 8, 'received', 'Der König wollte Frieden, aber seine Feinde waren stark.', NULL, 'The king wanted peace, but his enemies were strong.', 'پادشاه صلح می‌خواست اما دشمنانش قوی بودند.', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 51, 'B1', 9, 'sent', NULL, 'Musste er kämpfen oder konnte er verhandeln?', 'Did he have to fight or could he negotiate?', 'مجبور بود بجنگد یا توانست مذاکره کند؟', NULL, NULL FROM lessons WHERE day = 51;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 0, 'received', 'Wie wird Brot in Deutschland hergestellt?', NULL, 'How is bread made in Germany?', 'نان در آلمان چگونه تهیه می‌شود؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 1, 'sent', NULL, 'Das Brot wird aus Mehl, Wasser und Hefe gebacken.', 'Bread is baked from flour, water and yeast.', 'نان از آرد، آب و مخمر پخته می‌شود.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 2, 'received', 'Wird in Deutschland viel recycelt?', NULL, 'Is there a lot of recycling in Germany?', 'در آلمان زیاد بازیافت می‌شود؟', NULL, NULL FROM lessons WHERE day = 52;
