INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 4, 'received', 'Wann wird das neue Gebäude eröffnet?', NULL, 'When is the new building being opened?', 'ساختمان جدید کی افتتاح می‌شود؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 5, 'sent', NULL, 'Es wird nächsten Monat offiziell eröffnet.', 'It will be officially opened next month.', 'ماه آینده رسما افتتاح می‌شود.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 6, 'received', 'Wird Deutsch auch in Österreich gesprochen?', NULL, 'Is German also spoken in Austria?', 'در اتریش هم آلمانی صحبت می‌شود؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 7, 'sent', NULL, 'Ja, Deutsch wird in Deutschland, Österreich und der Schweiz gesprochen.', 'Yes, German is spoken in Germany, Austria and Switzerland.', 'بله، آلمانی در آلمان، اتریش و سوئیس صحبت می‌شود.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 8, 'received', 'Werden die Schüler heute geprüft?', NULL, 'Are the students being tested today?', 'امروز دانش‌آموزان امتحان می‌شوند؟', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 52, 'B1', 9, 'sent', NULL, 'Ja, heute werden alle Schüler in Mathematik geprüft.', 'Yes, today all students are being tested in mathematics.', 'بله، امروز همه دانش‌آموزان در ریاضی امتحان می‌شوند.', NULL, NULL FROM lessons WHERE day = 52;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 0, 'received', 'Kennst du den Mann, der dort steht?', NULL, 'Do you know the man who is standing there?', 'مردی که آنجا ایستاده را می‌شناسی؟', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 1, 'sent', NULL, 'Ja, das ist der Lehrer, der uns Deutsch unterrichtet.', 'Yes, that is the teacher who teaches us German.', 'بله، او معلمی است که به ما آلمانی درس می‌دهد.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 2, 'received', 'Wo ist das Buch, das ich dir geliehen habe?', NULL, 'Where is the book that I lent you?', 'کتابی که بهت قرض دادم کجاست؟', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 3, 'sent', NULL, 'Das Buch, das du mir geliehen hast, liegt auf dem Schreibtisch.', 'The book that you lent me is on the desk.', 'کتابی که بهم قرض دادی روی میز تحریر است.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 4, 'received', 'Die Frau, die neben mir sitzt, kommt aus Japan.', NULL, 'The woman who sits next to me comes from Japan.', 'زنی که کنار من نشسته اهل ژاپن است.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 5, 'sent', NULL, 'Interessant! Kennst du auch die Studenten, die aus Brasilien kommen?', 'Interesting! Do you also know the students who come from Brazil?', 'جالب! دانشجویانی که از برزیل آمده‌اند را هم می‌شناسی؟', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 6, 'received', 'Die Stadt, in der ich aufgewachsen bin, ist sehr klein.', NULL, 'The city in which I grew up is very small.', 'شهری که در آن بزرگ شدم خیلی کوچک است.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 7, 'sent', NULL, 'Ich komme aus einer Stadt, die am Meer liegt.', 'I come from a city that is by the sea.', 'من از شهری می‌آیم که کنار دریاست.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 8, 'received', 'Das Restaurant, das wir gestern besucht haben, war ausgezeichnet.', NULL, 'The restaurant that we visited yesterday was excellent.', 'رستورانی که دیروز رفتیم عالی بود.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 53, 'B1', 9, 'sent', NULL, 'Ja, das Essen, das wir bestellt haben, war fantastisch.', 'Yes, the food that we ordered was fantastic.', 'بله، غذایی که سفارش دادیم فوق‌العاده بود.', NULL, NULL FROM lessons WHERE day = 53;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 0, 'received', 'Wessen Auto ist das?', NULL, 'Whose car is that?', 'ماشین مال کیست؟', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 1, 'sent', NULL, 'Das ist das Auto meines Vaters.', 'That is my father''s car.', 'ماشین پدرم است.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 2, 'received', 'Wegen des schlechten Wetters bleiben wir zu Hause.', NULL, 'Because of the bad weather we are staying home.', 'به خاطر هوای بد خانه می‌مانیم.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 3, 'sent', NULL, 'Trotz des Regens möchte ich spazieren gehen.', 'Despite the rain I would like to go for a walk.', 'با وجود باران دلم می‌خواهد پیاده‌روی کنم.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 4, 'received', 'Die Meinung des Professors ist sehr wichtig.', NULL, 'The opinion of the professor is very important.', 'نظر استاد خیلی مهم است.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 5, 'sent', NULL, 'Ja, und die Ergebnisse der Forschung sind interessant.', 'Yes, and the results of the research are interesting.', 'بله، و نتایج تحقیقات جالب است.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 6, 'received', 'Innerhalb eines Jahres hat sie viel gelernt.', NULL, 'Within one year she learned a lot.', 'در عرض یک سال خیلی یاد گرفت.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 7, 'sent', NULL, 'Ja, während des letzten Semesters hat sie große Fortschritte gemacht.', 'Yes, during the last semester she made great progress.', 'بله، طی ترم گذشته پیشرفت زیادی کرد.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 8, 'received', 'Außerhalb der Stadt gibt es schöne Wanderwege.', NULL, 'Outside of the city there are beautiful hiking trails.', 'خارج از شهر مسیرهای پیاده‌روی زیبایی هست.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 54, 'B1', 9, 'sent', NULL, 'Am Ende des Weges liegt ein kleiner See.', 'At the end of the path there is a small lake.', 'انتهای مسیر یک دریاچه کوچک هست.', NULL, NULL FROM lessons WHERE day = 54;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 0, 'received', 'Können Sie mir sagen, wo der Bahnhof ist?', NULL, 'Can you tell me where the train station is?', 'می‌توانید بگویید ایستگاه قطار کجاست؟', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 1, 'sent', NULL, 'Ich weiß leider nicht, wo der Bahnhof genau ist.', 'Unfortunately I don''t know exactly where the station is.', 'متاسفانه نمی‌دانم ایستگاه دقیقا کجاست.', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 2, 'received', 'Weißt du, ob der Laden heute geöffnet hat?', NULL, 'Do you know if the shop is open today?', 'می‌دانی مغازه امروز باز است؟', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 3, 'sent', NULL, 'Ich bin nicht sicher, ob er heute auf hat.', 'I am not sure if it is open today.', 'مطمئن نیستم که امروز باز باشد.', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 4, 'received', 'Können Sie mir erklären, wie man ein Ticket kauft?', NULL, 'Can you explain to me how to buy a ticket?', 'می‌توانید توضیح دهید چطور بلیط بخرم؟', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 5, 'sent', NULL, 'Ich zeige Ihnen, wie der Automat funktioniert.', 'I will show you how the machine works.', 'نشانتان می‌دهم دستگاه چطور کار می‌کند.', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 6, 'received', 'Ich möchte wissen, wann der nächste Kurs beginnt.', NULL, 'I would like to know when the next course starts.', 'می‌خواهم بدانم کلاس بعدی کی شروع می‌شود.', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 7, 'sent', NULL, 'Ich frage nach, wann genau der Kurs anfängt.', 'I will ask when exactly the course starts.', 'می‌پرسم دقیقا کی کلاس شروع می‌شود.', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 8, 'received', 'Hat er gesagt, warum er nicht kommen kann?', NULL, 'Did he say why he can''t come?', 'گفت چرا نمی‌تواند بیاید؟', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 55, 'B1', 9, 'sent', NULL, 'Nein, er hat nicht gesagt, warum er absagen musste.', 'No, he didn''t say why he had to cancel.', 'نه، نگفت چرا مجبور شد لغو کند.', NULL, NULL FROM lessons WHERE day = 55;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 0, 'received', 'Was kann man für die Umwelt tun?', NULL, 'What can one do for the environment?', 'چه کاری می‌توان برای محیط زیست انجام داد؟', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 1, 'sent', NULL, 'Man kann weniger Auto fahren und mehr öffentliche Verkehrsmittel benutzen.', 'One can drive less and use more public transportation.', 'می‌توان کمتر ماشین سوار شد و بیشتر از حمل‌ونقل عمومی استفاده کرد.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 2, 'received', 'Wird das Klima wirklich wärmer?', NULL, 'Is the climate really getting warmer?', 'آب و هوا واقعا گرم‌تر می‌شود؟', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 3, 'sent', NULL, 'Ja, man kann die Veränderungen deutlich sehen.', 'Yes, one can clearly see the changes.', 'بله، تغییرات را به وضوح می‌توان دید.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 4, 'received', 'Trennst du deinen Müll?', NULL, 'Do you separate your waste?', 'زباله‌هایت را جدا می‌کنی؟', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 5, 'sent', NULL, 'Ja, in Deutschland muss man den Müll in verschiedene Tonnen trennen.', 'Yes, in Germany one has to separate waste into different bins.', 'بله، در آلمان باید زباله را در سطل‌های مختلف جدا کرد.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 6, 'received', 'Wie kann man Energie sparen?', NULL, 'How can one save energy?', 'چطور می‌توان انرژی صرفه‌جویی کرد؟', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 7, 'sent', NULL, 'Man sollte das Licht ausschalten und weniger heizen.', 'One should turn off lights and heat less.', 'باید چراغ‌ها را خاموش کرد و کمتر بخاری روشن کرد.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 8, 'received', 'In meiner Stadt gibt es viele Parks und Grünflächen.', NULL, 'In my city there are many parks and green spaces.', 'در شهر من پارک‌ها و فضای سبز زیادی هست.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 56, 'B1', 9, 'sent', NULL, 'Das ist schön. Die Natur ist wichtig für die Lebensqualität.', 'That is nice. Nature is important for quality of life.', 'عالیه. طبیعت برای کیفیت زندگی مهم است.', NULL, NULL FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 0, 'received', 'Liest du regelmäßig Nachrichten?', NULL, 'Do you read news regularly?', 'مرتب اخبار می‌خوانی؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 1, 'sent', NULL, 'Ja, ich lese jeden Morgen die Nachrichten online.', 'Yes, I read the news online every morning.', 'بله، هر صبح اخبار آنلاین می‌خوانم.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 2, 'received', 'Was sagt der Bericht über die Wirtschaft?', NULL, 'What does the report say about the economy?', 'گزارش درباره اقتصاد چه می‌گوید؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 3, 'sent', NULL, 'Der Bericht sagt, dass die Wirtschaft langsam wächst.', 'The report says that the economy is growing slowly.', 'گزارش می‌گوید که اقتصاد به آرامی رشد می‌کند.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 4, 'received', 'Der Journalist berichtet, dass es neue Gesetze geben wird.', NULL, 'The journalist reports that there will be new laws.', 'خبرنگار گزارش می‌دهد که قوانین جدیدی خواهد آمد.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 5, 'sent', NULL, 'Ich habe gehört, dass die Regierung mehr in Bildung investieren will.', 'I heard that the government wants to invest more in education.', 'شنیده‌ام که دولت می‌خواهد بیشتر در آموزش سرمایه‌گذاری کند.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 6, 'received', 'Glaubst du alles, was in den Medien steht?', NULL, 'Do you believe everything that is in the media?', 'همه چیزی که در رسانه‌ها هست باور می‌کنی؟', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 7, 'sent', NULL, 'Nein, man muss verschiedene Quellen vergleichen.', 'No, one has to compare different sources.', 'نه، باید منابع مختلف را مقایسه کرد.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 8, 'received', 'Soziale Medien spielen heute eine große Rolle.', NULL, 'Social media plays a big role today.', 'رسانه‌های اجتماعی امروزه نقش بزرگی دارند.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 57, 'B1', 9, 'sent', NULL, 'Ja, aber man muss vorsichtig sein mit Falschinformationen.', 'Yes, but one has to be careful with misinformation.', 'بله، ولی باید مراقب اطلاعات نادرست بود.', NULL, NULL FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 0, 'received', 'Wie bleibst du fit und gesund?', NULL, 'How do you stay fit and healthy?', 'چطور سالم و سرحال می‌مانی؟', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 1, 'sent', NULL, 'Ich versuche, jeden Tag Sport zu treiben, ohne es zu übertreiben.', 'I try to exercise every day without overdoing it.', 'سعی می‌کنم هر روز ورزش کنم بدون اینکه زیاده‌روی کنم.', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 2, 'received', 'Isst du gesund?', NULL, 'Do you eat healthy?', 'غذای سالم می‌خوری؟', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 3, 'sent', NULL, 'Ich esse viel Obst und Gemüse, statt Fastfood zu essen.', 'I eat a lot of fruit and vegetables instead of eating fast food.', 'میوه و سبزیجات زیاد می‌خورم به جای اینکه فست‌فود بخورم.', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 4, 'received', 'Schläfst du genug?', NULL, 'Do you sleep enough?', 'به اندازه کافی می‌خوابی؟', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 5, 'sent', NULL, 'Ich versuche acht Stunden zu schlafen, ohne den Wecker zu benutzen.', 'I try to sleep eight hours without using the alarm clock.', 'سعی می‌کنم هشت ساعت بخوابم بدون اینکه از زنگ ساعت استفاده کنم.', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'A2', 6, 'received', 'Rauchst du?', NULL, 'Do you smoke?', 'سیگار می‌کشی؟', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 7, 'sent', NULL, 'Nein, ich habe vor einem Jahr aufgehört zu rauchen.', 'No, I stopped smoking a year ago.', 'نه، یک سال پیش سیگار را ترک کردم.', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 8, 'received', 'Stress ist schlecht für die Gesundheit.', NULL, 'Stress is bad for health.', 'استرس برای سلامتی ضرر دارد.', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 58, 'B1', 9, 'sent', NULL, 'Ja, statt sich zu stressen, sollte man Pausen machen und sich entspannen.', 'Yes, instead of stressing, one should take breaks and relax.', 'بله، به جای استرس داشتن باید استراحت کرد و آرامش یافت.', NULL, NULL FROM lessons WHERE day = 58;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 0, 'received', 'Was denkst du über das Leben in Deutschland?', NULL, 'What do you think about life in Germany?', 'درباره زندگی در آلمان چه فکر می‌کنی؟', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 1, 'sent', NULL, 'Ich finde, dass das Leben hier gut organisiert ist.', 'I think that life here is well organized.', 'به نظرم زندگی اینجا خوب سازمان‌دهی شده.', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 2, 'received', 'Bist du damit einverstanden, dass Bildung kostenlos sein sollte?', NULL, 'Do you agree that education should be free?', 'موافقی که آموزش باید رایگان باشد؟', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 3, 'sent', NULL, 'Ja, ich bin der Meinung, dass jeder Zugang zu kostenloser Bildung haben sollte.', 'Yes, I am of the opinion that everyone should have access to free education.', 'بله، نظرم این است که همه باید به آموزش رایگان دسترسی داشته باشند.', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 4, 'received', 'Manche Leute meinen, dass Technologie das Leben komplizierter macht.', NULL, 'Some people think that technology makes life more complicated.', 'بعضی‌ها معتقدند که فناوری زندگی را پیچیده‌تر می‌کند.', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 5, 'sent', NULL, 'Da bin ich anderer Meinung. Ich glaube, dass Technologie vieles erleichtert.', 'I disagree. I believe that technology makes many things easier.', 'من نظر دیگری دارم. معتقدم که فناوری خیلی چیزها را آسان‌تر می‌کند.', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 6, 'received', 'Was hältst du von der öffentlichen Verkehrsanbindung?', NULL, 'What do you think of the public transport connections?', 'نظرت درباره حمل‌ونقل عمومی چیه؟', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 7, 'sent', NULL, 'Meiner Meinung nach ist der öffentliche Verkehr hier sehr gut.', 'In my opinion public transport here is very good.', 'به نظر من حمل‌ونقل عمومی اینجا خیلی خوب است.', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 8, 'received', 'Findest du, dass man eine Fremdsprache lernen muss?', NULL, 'Do you think one has to learn a foreign language?', 'فکر می‌کنی آدم باید زبان خارجی یاد بگیرد؟', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 59, 'B1', 9, 'sent', NULL, 'Auf jeden Fall! Ich bin überzeugt, dass Sprachen die Welt öffnen.', 'Absolutely! I am convinced that languages open the world.', 'قطعا! متقاعد هستم که زبان‌ها دنیا را باز می‌کنند.', NULL, NULL FROM lessons WHERE day = 59;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 0, 'received', 'Was hat dich am meisten überrascht, als du nach Deutschland kamst?', NULL, 'What surprised you most when you came to Germany?', 'وقتی به آلمان آمدی بیشتر از همه از چه چیزی تعجب کردی؟', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 1, 'sent', NULL, 'Bevor ich nach Deutschland kam, wusste ich nicht, dass Pünktlichkeit so wichtig ist.', 'Before I came to Germany, I didn''t know that punctuality is so important.', 'قبل از اینکه به آلمان بیایم نمی‌دانستم وقت‌شناسی اینقدر مهم است.', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 2, 'received', 'Gibt es große Unterschiede zwischen der deutschen und iranischen Kultur?', NULL, 'Are there big differences between German and Iranian culture?', 'بین فرهنگ آلمانی و ایرانی تفاوت‌های بزرگی هست؟', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 3, 'sent', NULL, 'Ja, nachdem ich einige Zeit hier gelebt habe, habe ich viele Unterschiede bemerkt.', 'Yes, after I lived here for some time, I noticed many differences.', 'بله، بعد از اینکه مدتی اینجا زندگی کردم تفاوت‌های زیادی دیدم.', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 4, 'received', 'Wie feiert man Neujahr im Iran?', NULL, 'How do you celebrate New Year in Iran?', 'در ایران سال نو چطور جشن گرفته می‌شود؟', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 5, 'sent', NULL, 'Während in Deutschland Silvester am 31. Dezember gefeiert wird, feiern wir Nowruz im März.', 'While in Germany New Year is celebrated on December 31st, we celebrate Nowruz in March.', 'در حالی که در آلمان سال نو ۳۱ دسامبر جشن گرفته می‌شود، ما نوروز را در مارس جشن می‌گیریم.', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 6, 'received', 'Was vermisst du am meisten aus deiner Heimat?', NULL, 'What do you miss most from your homeland?', 'بیشتر از همه از وطنت چه چیزی دلت تنگ شده؟', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 7, 'sent', NULL, 'Nachdem ich ein Jahr hier war, habe ich das iranische Essen am meisten vermisst.', 'After being here for a year, I missed Iranian food the most.', 'بعد از یک سال اینجا، بیشتر از همه دلم برای غذای ایرانی تنگ شده.', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 8, 'received', 'Ist es schwer, sich an eine neue Kultur anzupassen?', NULL, 'Is it hard to adapt to a new culture?', 'سازگار شدن با فرهنگ جدید سخت است؟', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 60, 'B1', 9, 'sent', NULL, 'Am Anfang war es schwer, aber während man neue Freunde findet, wird es leichter.', 'In the beginning it was hard, but while you make new friends, it gets easier.', 'اوایل سخت بود ولی در حالی که دوست‌های جدید پیدا می‌کنی آسان‌تر می‌شود.', NULL, NULL FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 0, 'received', 'Was würdest du machen, wenn du viel Geld hättest?', NULL, 'What would you do if you had a lot of money?', 'اگر پول زیادی داشتی چه کار می‌کردی؟', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 1, 'sent', NULL, 'Ich würde um die Welt reisen und viele Länder besuchen.', 'I would travel around the world and visit many countries.', 'دور دنیا سفر می‌کردم و کشورهای زیادی می‌دیدم.', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 2, 'received', 'Würdest du in Deutschland bleiben oder zurückgehen?', NULL, 'Would you stay in Germany or go back?', 'در آلمان می‌ماندی یا برمی‌گشتی؟', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 3, 'sent', NULL, 'Ich würde wahrscheinlich hier bleiben, weil ich mich hier wohlfühle.', 'I would probably stay here because I feel comfortable here.', 'احتمالا اینجا می‌ماندم چون اینجا احساس راحتی می‌کنم.', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 4, 'received', 'Wenn ich du wäre, würde ich mehr Deutsch üben.', NULL, 'If I were you, I would practice more German.', 'اگر جای تو بودم بیشتر آلمانی تمرین می‌کردم.', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 5, 'sent', NULL, 'Du hast Recht. Ich würde gern einen Tandempartner finden.', 'You are right. I would like to find a tandem partner.', 'حق با توست. دوست دارم یک شریک تمرین زبان پیدا کنم.', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 6, 'received', 'Würden Sie mir bitte den Weg zum Museum erklären?', NULL, 'Would you please explain the way to the museum?', 'لطفا مسیر موزه را توضیح می‌دهید؟', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 7, 'sent', NULL, 'Natürlich! An Ihrer Stelle würde ich den Bus Linie 5 nehmen.', 'Of course! In your place I would take bus line 5.', 'البته! به جای شما اتوبوس خط ۵ را می‌گرفتم.', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 8, 'received', 'Es wäre schön, wenn wir zusammen kochen würden.', NULL, 'It would be nice if we would cook together.', 'خوب بود اگر با هم آشپزی می‌کردیم.', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 61, 'B1', 9, 'sent', NULL, 'Ja, das würde mir großen Spaß machen!', 'Yes, that would be a lot of fun for me!', 'بله، خیلی لذت‌بخش می‌شد!', NULL, NULL FROM lessons WHERE day = 61;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 0, 'received', 'Wenn ich mehr Zeit hätte, würde ich ein Instrument lernen.', NULL, 'If I had more time, I would learn an instrument.', 'اگر وقت بیشتری داشتم یک ساز یاد می‌گرفتم.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 1, 'sent', NULL, 'Ich wäre froh, wenn ich besser Deutsch könnte.', 'I would be happy if I could speak better German.', 'خوشحال بودم اگر بهتر آلمانی بلد بودم.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 2, 'received', 'Hättest du Lust auf einen Spaziergang?', NULL, 'Would you like to go for a walk?', 'حوصله پیاده‌روی داری؟', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 3, 'sent', NULL, 'Ja, das wäre schön! Wenn es nicht regnen würde.', 'Yes, that would be nice! If it weren''t raining.', 'بله، خوب بود! اگر باران نمی‌بارید.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 4, 'received', 'An deiner Stelle wäre ich vorsichtiger.', NULL, 'In your place I would be more careful.', 'جای تو بودم مواظب‌تر بودم.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 5, 'sent', NULL, 'Du hast Recht. Ich hätte nicht so schnell fahren sollen.', 'You are right. I shouldn''t have driven so fast.', 'حق با توست. نباید اینقدر تند رانندگی می‌کردم.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 6, 'received', 'Könntest du mir bei den Hausaufgaben helfen?', NULL, 'Could you help me with the homework?', 'می‌توانستی با تکالیفم کمکم کنی؟', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 7, 'sent', NULL, 'Klar! Ich hätte jetzt Zeit. Was müsstest du machen?', 'Sure! I would have time now. What would you need to do?', 'البته! الان وقت دارم. چه کاری باید بکنی؟', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 8, 'received', 'Wenn wir früher angefangen hätten, wären wir jetzt fertig.', NULL, 'If we had started earlier, we would be finished now.', 'اگر زودتر شروع کرده بودیم الان تمام شده بود.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 62, 'B1', 9, 'sent', NULL, 'Ja, das stimmt. Nächstes Mal sollten wir früher anfangen.', 'Yes, that''s true. Next time we should start earlier.', 'بله، درسته. دفعه بعد باید زودتر شروع کنیم.', NULL, NULL FROM lessons WHERE day = 62;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 0, 'received', 'Wann wurde diese Kirche gebaut?', NULL, 'When was this church built?', 'این کلیسا کی ساخته شد؟', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 1, 'sent', NULL, 'Diese Kirche wurde im 15. Jahrhundert gebaut.', 'This church was built in the 15th century.', 'این کلیسا در قرن پانزدهم ساخته شد.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 2, 'received', 'Wurde der Dieb gefasst?', NULL, 'Was the thief caught?', 'دزد دستگیر شد؟', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 3, 'sent', NULL, 'Ja, er wurde gestern von der Polizei verhaftet.', 'Yes, he was arrested by the police yesterday.', 'بله، دیروز توسط پلیس بازداشت شد.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 4, 'received', 'Das Buch wurde in viele Sprachen übersetzt.', NULL, 'The book was translated into many languages.', 'کتاب به زبان‌های زیادی ترجمه شد.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 5, 'sent', NULL, 'Ja, es ist auch ins Persische übersetzt worden.', 'Yes, it has also been translated into Persian.', 'بله، به فارسی هم ترجمه شده است.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 6, 'received', 'Wann wurde das Brandenburger Tor errichtet?', NULL, 'When was the Brandenburg Gate erected?', 'دروازه براندنبورگ کی ساخته شد؟', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 7, 'sent', NULL, 'Es wurde Ende des 18. Jahrhunderts errichtet.', 'It was erected at the end of the 18th century.', 'اواخر قرن هجدهم ساخته شد.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 8, 'received', 'Die Straße wird gerade repariert.', NULL, 'The street is being repaired right now.', 'خیابان در حال تعمیر است.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 63, 'B1', 9, 'sent', NULL, 'Ja, sie wurde letzte Woche gesperrt und wird nächste Woche wieder geöffnet.', 'Yes, it was closed last week and will be opened again next week.', 'بله، هفته پیش بسته شد و هفته آینده دوباره باز می‌شود.', NULL, NULL FROM lessons WHERE day = 63;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 0, 'received', 'Kennst du den neuen Studenten in unserem Kurs?', NULL, 'Do you know the new student in our course?', 'دانشجوی جدید کلاسمان را می‌شناسی؟', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 1, 'sent', NULL, 'Ja, ich habe dem Studenten gestern bei der Aufgabe geholfen.', 'Yes, I helped the student with the assignment yesterday.', 'بله، دیروز به دانشجو در تکلیف کمک کردم.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 2, 'received', 'Der Name des Herrn ist mir leider entfallen.', NULL, 'The gentleman''s name unfortunately slipped my mind.', 'متاسفانه نام آن آقا یادم رفته.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 3, 'sent', NULL, 'Er heißt Herr Schmidt. Er ist ein Kollege meines Nachbarn.', 'His name is Mr. Schmidt. He is a colleague of my neighbor.', 'نامش آقای اشمیت است. همکار همسایه‌ام است.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 4, 'received', 'Ich habe einen Termin beim Präsidenten der Universität.', NULL, 'I have an appointment with the president of the university.', 'با رئیس دانشگاه وقت ملاقات دارم.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 5, 'sent', NULL, 'Bei welchem Experten warst du zur Beratung?', 'Which expert did you go to for advice?', 'پیش کدام کارشناس برای مشاوره رفتی؟', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 6, 'received', 'Ich war beim Spezialisten für Herzerkrankungen.', NULL, 'I was at the specialist for heart diseases.', 'پیش متخصص بیماری‌های قلبی بودم.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 7, 'sent', NULL, 'Hoffentlich hat der Spezialist dir gute Nachrichten gegeben.', 'Hopefully the specialist gave you good news.', 'امیدوارم متخصص خبرهای خوبی داده باشد.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 8, 'received', 'Der Fotograf hat den Diplomaten bei der Konferenz fotografiert.', NULL, 'The photographer photographed the diplomat at the conference.', 'عکاس از دیپلمات در کنفرانس عکس گرفت.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 64, 'B1', 9, 'sent', NULL, 'Die Rede des Philosophen war sehr beeindruckend.', 'The speech of the philosopher was very impressive.', 'سخنرانی فیلسوف بسیار تاثیرگذار بود.', NULL, NULL FROM lessons WHERE day = 64;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 0, 'received', 'Warum bist du gestern nicht gekommen?', NULL, 'Why didn''t you come yesterday?', 'چرا دیروز نیامدی؟', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 1, 'sent', NULL, 'Ich habe leider nicht kommen können, weil ich krank war.', 'Unfortunately I was not able to come because I was sick.', 'متاسفانه نتوانستم بیایم چون مریض بودم.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 2, 'received', 'Hat Maria das Projekt allein machen müssen?', NULL, 'Did Maria have to do the project alone?', 'ماریا مجبور شد پروژه را تنها انجام بدهد؟', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 3, 'sent', NULL, 'Ja, sie hat es allein machen müssen, weil niemand ihr geholfen hat.', 'Yes, she had to do it alone because nobody helped her.', 'بله، مجبور شد تنها انجام بدهد چون کسی کمکش نکرد.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 4, 'received', 'Hast du den Film sehen wollen?', NULL, 'Did you want to see the movie?', 'خواستی فیلم را ببینی؟', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 5, 'sent', NULL, 'Ja, ich habe ihn sehen wollen, aber ich habe keine Karten bekommen können.', 'Yes, I wanted to see it but I couldn''t get tickets.', 'بله، می‌خواستم ببینم ولی نتوانستم بلیط بگیرم.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 6, 'received', 'Sie hat nicht mitkommen dürfen.', NULL, 'She was not allowed to come along.', 'اجازه نداشت بیاید.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 7, 'sent', NULL, 'Schade! Sie hätte bestimmt gern mitkommen wollen.', 'Too bad! She certainly would have liked to come along.', 'حیف! حتما دوست داشت بیاید.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 8, 'received', 'Er hat die Aufgabe nicht verstehen können.', NULL, 'He was not able to understand the assignment.', 'نتوانست تکلیف را بفهمد.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 65, 'B1', 9, 'sent', NULL, 'Ich hätte ihm helfen sollen, aber ich habe es nicht gewusst.', 'I should have helped him, but I didn''t know.', 'باید کمکش می‌کردم ولی نمی‌دانستم.', NULL, NULL FROM lessons WHERE day = 65;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 0, 'received', 'Möchten Sie kaltes Wasser oder warmen Tee?', NULL, 'Would you like cold water or warm tea?', 'آب سرد می‌خواهید یا چای گرم؟', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 1, 'sent', NULL, 'Kaltes Wasser, bitte. Bei heißem Wetter trinke ich lieber Wasser.', 'Cold water, please. In hot weather I prefer drinking water.', 'آب سرد، لطفا. در هوای گرم ترجیح می‌دهم آب بنوشم.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 2, 'received', 'Auf dem Markt gibt es frisches Obst und frisches Gemüse.', NULL, 'At the market there is fresh fruit and fresh vegetables.', 'در بازار میوه تازه و سبزیجات تازه هست.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 3, 'sent', NULL, 'Ich kaufe gern frisches Brot vom Bäcker.', 'I like to buy fresh bread from the baker.', 'از نانوایی نان تازه می‌خرم.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 4, 'received', 'Mit großer Freude lade ich Sie zur Feier ein.', NULL, 'With great pleasure I invite you to the celebration.', 'با کمال خوشحالی شما را به جشن دعوت می‌کنم.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 5, 'sent', NULL, 'Vielen Dank! Ich komme mit großem Interesse.', 'Thank you! I come with great interest.', 'خیلی ممنون! با علاقه زیاد می‌آیم.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 6, 'received', 'Nach langem Überlegen habe ich mich entschieden.', NULL, 'After long deliberation I have decided.', 'بعد از فکر زیاد تصمیم گرفتم.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 7, 'sent', NULL, 'Gut! Trotz schlechten Wetters gehen wir wandern.', 'Good! Despite bad weather we are going hiking.', 'خوب! با وجود هوای بد پیاده‌روی می‌رویم.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 8, 'received', 'Deutscher Wein ist weltbekannt.', NULL, 'German wine is world-famous.', 'شراب آلمانی در جهان مشهور است.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 66, 'B1', 9, 'sent', NULL, 'Ja, besonders weißer Wein aus dem Rheintal.', 'Yes, especially white wine from the Rhine valley.', 'بله، مخصوصا شراب سفید از دره راین.', NULL, NULL FROM lessons WHERE day = 66;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 0, 'received', 'Hast du schon die Bewerbung geschrieben?', NULL, 'Have you already written the application?', 'رزومه را نوشته‌ای؟', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 1, 'sent', NULL, 'Ja, ich beginne mit: Sehr geehrte Damen und Herren.', 'Yes, I begin with: Dear Sir or Madam.', 'بله، شروع می‌کنم با: خانم‌ها و آقایان محترم.', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 2, 'received', 'Wie schließt man einen formellen Brief ab?', NULL, 'How do you close a formal letter?', 'نامه رسمی را چطور تمام می‌کنند؟', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 3, 'sent', NULL, 'Man schreibt: Mit freundlichen Grüßen, und dann den Namen.', 'You write: With kind regards, and then the name.', 'می‌نویسیم: با احترام، و سپس نام.', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 4, 'received', 'Ich möchte mich über den schlechten Service beschweren.', NULL, 'I would like to complain about the bad service.', 'می‌خواهم درباره سرویس بد شکایت کنم.', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 5, 'sent', NULL, 'Sie könnten schreiben: Hiermit möchte ich mich über den mangelhaften Service beschweren.', 'You could write: Hereby I would like to complain about the poor service.', 'می‌توانید بنویسید: بدینوسیله مایلم از خدمات نامناسب شکایت کنم.', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 6, 'received', 'Wie bittet man höflich um eine Antwort?', NULL, 'How does one politely ask for a reply?', 'چطور مؤدبانه درخواست پاسخ می‌کنند؟', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 7, 'sent', NULL, 'Man kann schreiben: Ich würde mich über eine baldige Rückmeldung freuen.', 'One can write: I would be happy about a prompt response.', 'می‌توان نوشت: از پاسخ سریع شما خوشحال می‌شوم.', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 8, 'received', 'Soll ich den Brief per Post oder per E-Mail schicken?', NULL, 'Should I send the letter by post or by email?', 'نامه را پستی بفرستم یا ایمیل؟', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 67, 'B1', 9, 'sent', NULL, 'Heutzutage wird meistens per E-Mail kommuniziert.', 'Nowadays communication is mostly done by email.', 'امروزه بیشتر از طریق ایمیل ارتباط برقرار می‌شود.', NULL, NULL FROM lessons WHERE day = 67;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 0, 'received', 'Erzählen Sie uns bitte etwas über sich.', NULL, 'Please tell us something about yourself.', 'لطفا کمی درباره خودتان بگویید.', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 1, 'sent', NULL, 'Ich habe an der Universität Teheran Informatik studiert und arbeite seit drei Jahren als Entwickler.', 'I studied computer science at the University of Tehran and have been working as a developer for three years.', 'در دانشگاه تهران کامپیوتر خوانده‌ام و سه سال است به عنوان برنامه‌نویس کار می‌کنم.', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 2, 'received', 'Warum haben Sie sich bei uns beworben?', NULL, 'Why did you apply to us?', 'چرا پیش ما درخواست دادید؟', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 3, 'sent', NULL, 'Ich habe mich beworben, weil Ihre Firma für innovative Projekte bekannt ist.', 'I applied because your company is known for innovative projects.', 'درخواست دادم چون شرکت شما به خاطر پروژه‌های نوآورانه مشهور است.', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 4, 'received', 'Was sind Ihre Stärken?', NULL, 'What are your strengths?', 'نقاط قوت شما چیست؟', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 5, 'sent', NULL, 'Ich bin teamfähig, zuverlässig und kann gut Probleme lösen.', 'I am a team player, reliable and good at solving problems.', 'کار تیمی بلدم، قابل اعتماد هستم و در حل مسائل خوب هستم.', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B2', 6, 'received', 'Wo sehen Sie sich in fünf Jahren?', NULL, 'Where do you see yourself in five years?', 'پنج سال بعد خودتان را کجا می‌بینید؟', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B2', 7, 'sent', NULL, 'In fünf Jahren möchte ich eine leitende Position in der Softwareentwicklung haben.', 'In five years I would like to have a leading position in software development.', 'پنج سال بعد دوست دارم پست مدیریتی در توسعه نرم‌افزار داشته باشم.', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 8, 'received', 'Haben Sie noch Fragen an uns?', NULL, 'Do you have any questions for us?', 'سوالی از ما دارید؟', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 68, 'B1', 9, 'sent', NULL, 'Ja, wie sieht ein typischer Arbeitstag in Ihrem Team aus?', 'Yes, what does a typical workday in your team look like?', 'بله، یک روز کاری معمولی در تیم شما چه شکلی است؟', NULL, NULL FROM lessons WHERE day = 68;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 0, 'received', 'Guten Tag, ich rufe wegen der Wohnungsanzeige an.', NULL, 'Good day, I am calling about the apartment ad.', 'روز بخیر، بابت آگهی آپارتمان تماس می‌گیرم.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 1, 'sent', NULL, 'Wie groß ist die Wohnung und wie viel kostet die Miete?', 'How big is the apartment and how much is the rent?', 'آپارتمان چقدر بزرگ است و اجاره چقدر است؟', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 2, 'received', 'Die Wohnung hat 65 Quadratmeter und kostet 750 Euro warm.', NULL, 'The apartment has 65 square meters and costs 750 euros warm.', 'آپارتمان ۶۵ متر مربع است و ۷۵۰ یورو با هزینه‌ها اجاره است.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 3, 'sent', NULL, 'Wenn ich die Wohnung besichtigen könnte, würde ich mich sehr freuen.', 'If I could view the apartment, I would be very happy.', 'اگر بتوانم آپارتمان را ببینم خیلی خوشحال می‌شوم.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 4, 'received', 'Sie können morgen um 14 Uhr vorbeikommen.', NULL, 'You can come by tomorrow at 2 PM.', 'فردا ساعت ۲ بعدازظهر می‌توانید بیایید.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 5, 'sent', NULL, 'Perfekt! Brauche ich bestimmte Unterlagen für die Bewerbung?', 'Perfect! Do I need certain documents for the application?', 'عالی! مدارک خاصی برای درخواست لازم دارم؟', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 6, 'received', 'Ja, bringen Sie bitte eine Schufa-Auskunft und Ihre letzten drei Gehaltsabrechnungen mit.', NULL, 'Yes, please bring a Schufa report and your last three pay slips.', 'بله، لطفا گزارش شوفا و سه فیش حقوقی آخرتان را بیاورید.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 7, 'sent', NULL, 'Gibt es Haustiere in dem Haus? Ich habe eine kleine Katze.', 'Are there pets in the building? I have a small cat.', 'حیوان خانگی در ساختمان هست؟ من یک گربه کوچک دارم.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 8, 'received', 'Haustiere sind erlaubt, solange sie die Nachbarn nicht stören.', NULL, 'Pets are allowed as long as they don''t disturb the neighbors.', 'حیوانات خانگی مجاز هستند تا زمانی که مزاحم همسایه‌ها نشوند.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 69, 'B1', 9, 'sent', NULL, 'Wunderbar! Ich freue mich auf den Besichtigungstermin.', 'Wonderful! I look forward to the viewing appointment.', 'عالی! منتظر وقت بازدید هستم.', NULL, NULL FROM lessons WHERE day = 69;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 0, 'received', 'Was denkst du über die Integration von Ausländern?', NULL, 'What do you think about the integration of foreigners?', 'درباره ادغام خارجی‌ها چه فکر می‌کنی؟', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 1, 'sent', NULL, 'Obwohl es Herausforderungen gibt, glaube ich, dass Integration möglich ist.', 'Although there are challenges, I believe that integration is possible.', 'با وجود چالش‌ها، معتقدم ادغام ممکن است.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 2, 'received', 'Viele Migranten finden schwer Arbeit.', NULL, 'Many migrants have difficulty finding work.', 'خیلی از مهاجران سخت کار پیدا می‌کنند.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 3, 'sent', NULL, 'Trotzdem geben viele nicht auf und lernen die Sprache.', 'Nevertheless many don''t give up and learn the language.', 'با این حال خیلی‌ها تسلیم نمی‌شوند و زبان یاد می‌گیرند.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 4, 'received', 'Obwohl er seit zehn Jahren hier lebt, fühlt er sich manchmal fremd.', NULL, 'Although he has lived here for ten years, he sometimes feels foreign.', 'با وجود اینکه ده سال است اینجا زندگی می‌کند، گاهی احساس غربت می‌کند.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 5, 'sent', NULL, 'Das verstehe ich. Trotzdem ist Deutschland sein Zuhause geworden.', 'I understand that. Nevertheless Germany has become his home.', 'درکش می‌کنم. با این حال آلمان خانه‌اش شده.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 6, 'received', 'Die Gesellschaft sollte offener für andere Kulturen sein.', NULL, 'Society should be more open to other cultures.', 'جامعه باید نسبت به فرهنگ‌های دیگر بازتر باشد.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 7, 'sent', NULL, 'Ich stimme zu. Obwohl es Fortschritte gibt, muss noch viel getan werden.', 'I agree. Although there is progress, much still needs to be done.', 'موافقم. با وجود پیشرفت‌ها هنوز کارهای زیادی باید انجام شود.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 8, 'received', 'Chancengleichheit ist ein wichtiges Thema.', NULL, 'Equal opportunity is an important topic.', 'برابری فرصت‌ها موضوع مهمی است.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 70, 'B1', 9, 'sent', NULL, 'Ja, trotz aller Schwierigkeiten sollten wir für Gleichberechtigung kämpfen.', 'Yes, despite all difficulties we should fight for equal rights.', 'بله، با وجود همه مشکلات باید برای برابری حقوق تلاش کنیم.', NULL, NULL FROM lessons WHERE day = 70;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 0, 'received', 'Was machst du am Wochenende?', NULL, 'What are you doing on the weekend?', 'آخر هفته چه کار می‌کنی؟', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 1, 'sent', NULL, 'Ich werde am Samstag ins Kino gehen.', 'I will go to the cinema on Saturday.', 'شنبه به سینما خواهم رفت.', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 2, 'received', 'Welchen Film möchtest du sehen?', NULL, 'Which movie would you like to see?', 'کدام فیلم را می‌خواهی ببینی؟', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 3, 'sent', NULL, 'Ich möchte den neuen deutschen Film sehen.', 'I want to see the new German film.', 'می‌خواهم فیلم جدید آلمانی را ببینم.', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 4, 'received', 'Und am Sonntag? Hast du auch Pläne?', NULL, 'And on Sunday? Do you also have plans?', 'و یکشنبه؟ برنامه‌ای هم داری؟', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 5, 'sent', NULL, 'Am Sonntag werde ich meine Großeltern besuchen.', 'On Sunday I will visit my grandparents.', 'یکشنبه به دیدن پدربزرگ و مادربزرگم خواهم رفت.', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 6, 'received', 'Das klingt schön. Wohnen sie weit weg?', NULL, 'That sounds nice. Do they live far away?', 'قشنگ به نظر می‌رسد. دور زندگی می‌کنند؟', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 7, 'sent', NULL, 'Nein, sie wohnen nur dreißig Minuten entfernt.', 'No, they live only thirty minutes away.', 'نه، فقط سی دقیقه فاصله دارند.', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 8, 'received', 'Dann wünsche ich dir ein schönes Wochenende!', NULL, 'Then I wish you a nice weekend!', 'پس آخر هفته خوبی برایت آرزو می‌کنم!', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 71, 'A2', 9, 'sent', NULL, 'Danke, dir auch! Bis Montag.', 'Thanks, you too! See you Monday.', 'ممنون، تو هم همینطور! تا دوشنبه.', NULL, NULL FROM lessons WHERE day = 71;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 0, 'received', 'Lass uns heute zusammen kochen!', NULL, 'Let''s cook together today!', 'بیا امروز با هم آشپزی کنیم!', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 1, 'sent', NULL, 'Gute Idee! Was sollen wir kochen?', 'Good idea! What should we cook?', 'ایده خوبی! چی بپزیم؟', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 2, 'received', 'Wie wäre es mit Spaghetti Bolognese?', NULL, 'How about spaghetti Bolognese?', 'اسپاگتی بولونز چطوره؟', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 3, 'sent', NULL, 'Perfekt! Ich kaufe die Zutaten.', 'Perfect! I''ll buy the ingredients.', 'عالی! من مواد اولیه را می‌خرم.', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 4, 'received', 'Wir brauchen Tomaten, Hackfleisch und Nudeln.', NULL, 'We need tomatoes, minced meat, and pasta.', 'ما گوجه، گوشت چرخ‌کرده و ماکارونی نیاز داریم.', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 5, 'sent', NULL, 'Soll ich auch Käse und Brot mitbringen?', 'Should I also bring cheese and bread?', 'پنیر و نان هم بیاورم؟', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 6, 'received', 'Ja, bitte. Und vergiss das Olivenöl nicht!', NULL, 'Yes, please. And don''t forget the olive oil!', 'بله، لطفاً. و روغن زیتون را فراموش نکن!', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 7, 'sent', NULL, 'Keine Sorge, ich vergesse nichts.', 'No worries, I won''t forget anything.', 'نگران نباش، چیزی فراموش نمی‌کنم.', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 8, 'received', 'Schneide bitte die Zwiebeln klein.', NULL, 'Please cut the onions small.', 'لطفاً پیازها را ریز خرد کن.', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 72, 'A2', 9, 'sent', NULL, 'In Ordnung. Das Essen riecht schon gut!', 'Alright. The food already smells good!', 'باشه. غذا بوی خوبی می‌دهد!', NULL, NULL FROM lessons WHERE day = 72;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 0, 'received', 'Guten Tag! Möchten Sie sich anmelden?', NULL, 'Good day! Would you like to register?', 'روز بخیر! می‌خواهید ثبت‌نام کنید؟', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 1, 'sent', NULL, 'Ja, ich möchte gern Mitglied werden.', 'Yes, I would like to become a member.', 'بله، می‌خواهم عضو شوم.', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 2, 'received', 'Wir haben verschiedene Angebote. Wie oft möchten Sie trainieren?', NULL, 'We have different offers. How often would you like to train?', 'ما پیشنهادات مختلفی داریم. چند وقت یکبار می‌خواهید تمرین کنید؟', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 3, 'sent', NULL, 'Ich möchte dreimal pro Woche kommen.', 'I want to come three times per week.', 'می‌خواهم هفته‌ای سه بار بیایم.', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 4, 'received', 'Dann empfehle ich das Standardpaket für vierzig Euro im Monat.', NULL, 'Then I recommend the standard package for forty euros per month.', 'پس بسته استاندارد را برای چهل یورو در ماه پیشنهاد می‌کنم.', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 5, 'sent', NULL, 'Kann ich auch an Kursen teilnehmen?', 'Can I also participate in classes?', 'آیا می‌توانم در کلاس‌ها هم شرکت کنم؟', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 6, 'received', 'Ja, Yoga und Spinning sind inklusive.', NULL, 'Yes, yoga and spinning are included.', 'بله، یوگا و اسپینینگ شامل می‌شود.', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 7, 'sent', NULL, 'Das klingt gut. Wo kann ich mich umziehen?', 'That sounds good. Where can I change?', 'خوب به نظر می‌رسد. کجا می‌توانم لباس عوض کنم؟', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 8, 'received', 'Die Umkleidekabinen sind dort hinten links.', NULL, 'The changing rooms are back there on the left.', 'رختکن‌ها آنجا سمت چپ هستند.', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 73, 'A2', 9, 'sent', NULL, 'Vielen Dank! Ich fange gleich an.', 'Thank you! I''ll start right away.', 'خیلی ممنون! الان شروع می‌کنم.', NULL, NULL FROM lessons WHERE day = 73;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 0, 'received', 'Schön, dass du gekommen bist! Komm rein.', NULL, 'Nice that you came! Come in.', 'خوشحالم که آمدی! بیا تو.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 1, 'sent', NULL, 'Danke für die Einladung! Ich habe einen Kuchen mitgebracht.', 'Thanks for the invitation! I brought a cake.', 'ممنون برای دعوت! یک کیک آورده‌ام.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 2, 'received', 'Oh, wie nett! Setz dich bitte. Möchtest du etwas trinken?', NULL, 'Oh, how nice! Please sit down. Would you like something to drink?', 'اوه، چه لطف! لطفاً بنشین. چیزی می‌خواهی بنوشی؟', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 3, 'sent', NULL, 'Gerne, ein Tee wäre schön.', 'Gladly, a tea would be nice.', 'با کمال میل، یک چای خوب می‌شد.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 4, 'received', 'Erzähl mal, wie war dein Urlaub in Italien?', NULL, 'Tell me, how was your vacation in Italy?', 'بگو ببینم، تعطیلاتت در ایتالیا چطور بود؟', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 5, 'sent', NULL, 'Es war wunderbar! Wir sind viel gewandert und haben lecker gegessen.', 'It was wonderful! We hiked a lot and ate delicious food.', 'فوق‌العاده بود! خیلی پیاده‌روی کردیم و غذاهای خوشمزه خوردیم.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 6, 'received', 'Seid ihr auch nach Rom gefahren?', NULL, 'Did you also go to Rome?', 'به رم هم رفتید؟', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 7, 'sent', NULL, 'Ja, wir sind drei Tage in Rom geblieben. Die Stadt ist unglaublich.', 'Yes, we stayed three days in Rome. The city is incredible.', 'بله، سه روز در رم ماندیم. شهر باورنکردنی است.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 8, 'received', 'Das klingt toll! Ich möchte auch mal nach Italien reisen.', NULL, 'That sounds great! I would also like to travel to Italy sometime.', 'عالی به نظر می‌رسد! من هم دوست دارم یه بار به ایتالیا سفر کنم.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 74, 'B1', 9, 'sent', NULL, 'Du solltest unbedingt gehen! Ich kann dir Tipps geben.', 'You should definitely go! I can give you tips.', 'حتماً باید بروی! می‌توانم بهت راهنمایی بدهم.', NULL, NULL FROM lessons WHERE day = 74;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 0, 'received', 'Ich habe gehört, dass du nach Hamburg ziehst.', NULL, 'I heard that you''re moving to Hamburg.', 'شنیدم که داری به هامبورگ نقل مکان می‌کنی.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 1, 'sent', NULL, 'Ja, weil ich dort eine neue Arbeit gefunden habe.', 'Yes, because I found a new job there.', 'بله، چون آنجا یک کار جدید پیدا کرده‌ام.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 2, 'received', 'Das ist aufregend! Hast du schon eine Wohnung?', NULL, 'That''s exciting! Do you already have an apartment?', 'هیجان‌انگیزه! آپارتمان پیدا کرده‌ای؟', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 3, 'sent', NULL, 'Noch nicht. Ich suche eine Zweizimmerwohnung in der Stadtmitte.', 'Not yet. I''m looking for a two-room apartment in the city center.', 'هنوز نه. دنبال یک آپارتمان دو اتاقه در مرکز شهر می‌گردم.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 4, 'received', 'In Hamburg sind die Mieten leider ziemlich hoch.', NULL, 'In Hamburg the rents are unfortunately quite high.', 'متأسفانه اجاره در هامبورگ خیلی بالاست.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 5, 'sent', NULL, 'Ich weiß, dass es teuer ist, aber mein Gehalt ist auch besser.', 'I know that it''s expensive, but my salary is also better.', 'می‌دانم که گران است، ولی حقوقم هم بهتر شده.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 6, 'received', 'Kennst du dort schon jemanden?', NULL, 'Do you already know anyone there?', 'آنجا کسی را می‌شناسی؟', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 7, 'sent', NULL, 'Ja, ein alter Freund von mir wohnt dort.', 'Yes, an old friend of mine lives there.', 'بله، یک دوست قدیمی‌ام آنجا زندگی می‌کند.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 8, 'received', 'Das ist gut, dann bist du nicht ganz allein.', NULL, 'That''s good, then you''re not completely alone.', 'خوبه، پس کاملاً تنها نیستی.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 75, 'B1', 9, 'sent', NULL, 'Genau. Ich freue mich auf den Neuanfang.', 'Exactly. I''m looking forward to the new beginning.', 'دقیقاً. از شروع جدید خوشحالم.', NULL, NULL FROM lessons WHERE day = 75;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 0, 'received', 'Entschuldigung, wann kommt der nächste Bus?', NULL, 'Excuse me, when does the next bus come?', 'ببخشید، اتوبوس بعدی کی می‌آید؟', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 1, 'sent', NULL, 'Der Bus hat Verspätung, weil es einen Unfall gibt.', 'The bus is delayed because there''s an accident.', 'اتوبوس تأخیر دارد، چون تصادفی شده.', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 2, 'received', 'Oh nein! Wie lange muss ich warten?', NULL, 'Oh no! How long do I have to wait?', 'وای نه! چقدر باید صبر کنم؟', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 3, 'sent', NULL, 'Ungefähr zwanzig Minuten. Oder Sie nehmen die U-Bahn.', 'About twenty minutes. Or you take the subway.', 'تقریباً بیست دقیقه. یا مترو بگیرید.', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 4, 'received', 'Wo ist die nächste U-Bahn-Station?', NULL, 'Where is the nearest subway station?', 'نزدیک‌ترین ایستگاه مترو کجاست؟', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 5, 'sent', NULL, 'Gehen Sie geradeaus und dann links. Es sind fünf Minuten.', 'Go straight and then left. It''s five minutes.', 'مستقیم بروید و بعد بپیچید سمت چپ. پنج دقیقه راه است.', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 6, 'received', 'Welche Linie fährt zum Hauptbahnhof?', NULL, 'Which line goes to the main station?', 'کدام خط به ایستگاه مرکزی می‌رود؟', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 7, 'sent', NULL, 'Sie brauchen die Linie drei, Richtung Zentrum.', 'You need line three, direction center.', 'خط سه را باید بگیرید، جهت مرکز شهر.', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 8, 'received', 'Muss ich umsteigen?', NULL, 'Do I have to transfer?', 'باید عوض کنم؟', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 76, 'A2', 9, 'sent', NULL, 'Nein, es ist direkt. Vier Stationen bis zum Hauptbahnhof.', 'No, it''s direct. Four stations to the main station.', 'نه، مستقیم است. چهار ایستگاه تا ایستگاه مرکزی.', NULL, NULL FROM lessons WHERE day = 76;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 0, 'received', 'Guten Morgen! Was darf es sein?', NULL, 'Good morning! What can I get you?', 'صبح بخیر! چه میل دارید؟', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 1, 'sent', NULL, 'Ich hätte gern ein Kilo Äpfel, bitte.', 'I would like one kilo of apples, please.', 'لطفاً یک کیلو سیب می‌خواهم.', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 2, 'received', 'Gerne. Möchten Sie noch etwas?', NULL, 'Gladly. Would you like anything else?', 'حتماً. چیز دیگری می‌خواهید؟', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 3, 'sent', NULL, 'Ja, ein halbes Kilo Tomaten und eine Gurke.', 'Yes, half a kilo of tomatoes and a cucumber.', 'بله، نیم کیلو گوجه و یک خیار.', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 4, 'received', 'Die Tomaten sind heute besonders frisch.', NULL, 'The tomatoes are especially fresh today.', 'گوجه‌ها امروز خیلی تازه هستند.', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 5, 'sent', NULL, 'Wunderbar. Was kostet das alles zusammen?', 'Wonderful. What does it all cost together?', 'عالی. همه با هم چقدر می‌شود؟', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 6, 'received', 'Das macht fünf Euro fünfzig.', NULL, 'That''s five euros fifty.', 'پنج یورو و پنجاه سنت می‌شود.', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 7, 'sent', NULL, 'Hier sind sechs Euro. Stimmt so.', 'Here are six euros. Keep the change.', 'بفرمایید شش یورو. بقیه‌اش مال شما.', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 8, 'received', 'Vielen Dank! Kommen Sie nächste Woche wieder?', NULL, 'Thank you! Will you come again next week?', 'خیلی ممنون! هفته بعد هم می‌آیید؟', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 77, 'A2', 9, 'sent', NULL, 'Natürlich! Ich kaufe immer hier ein.', 'Of course! I always shop here.', 'البته! من همیشه اینجا خرید می‌کنم.', NULL, NULL FROM lessons WHERE day = 77;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 0, 'received', 'Mein Geburtstag ist nächsten Samstag. Ich mache eine Party!', NULL, 'My birthday is next Saturday. I''m having a party!', 'تولدم شنبه آینده است. مهمانی می‌گیرم!', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 1, 'sent', NULL, 'Toll! Wenn du möchtest, kann ich beim Kochen helfen.', 'Great! If you want, I can help with cooking.', 'عالی! اگر بخواهی، می‌توانم در آشپزی کمک کنم.', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 2, 'received', 'Das wäre super! Kannst du einen Salat machen?', NULL, 'That would be great! Can you make a salad?', 'عالی می‌شد! می‌توانی سالاد درست کنی؟', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 3, 'sent', NULL, 'Klar! Und wenn du willst, bringe ich auch Getränke mit.', 'Sure! And if you want, I''ll also bring drinks.', 'حتماً! و اگر بخواهی، نوشیدنی هم می‌آورم.', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 4, 'received', 'Wie viele Leute kommen ungefähr?', NULL, 'How many people are coming approximately?', 'تقریباً چند نفر می‌آیند؟', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 5, 'sent', NULL, 'Wenn alle zusagen, sind es etwa fünfzehn Personen.', 'If everyone says yes, it''s about fifteen people.', 'اگر همه قبول کنند، حدود پانزده نفر می‌شوند.', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 6, 'received', 'Sollen wir Musik organisieren oder einen DJ holen?', NULL, 'Should we organize music or get a DJ?', 'موسیقی ترتیب بدهیم یا دی‌جی بیاوریم؟', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 7, 'sent', NULL, 'Ich denke, eine Playlist reicht. Wenn das Wetter gut ist, können wir im Garten feiern.', 'I think a playlist is enough. If the weather is good, we can celebrate in the garden.', 'فکر می‌کنم یک پلی‌لیست کافی باشد. اگر هوا خوب باشد، می‌توانیم در باغ جشن بگیریم.', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 8, 'received', 'Gute Idee! Und wenn es regnet?', NULL, 'Good idea! And if it rains?', 'ایده خوبیه! و اگر باران ببارد؟', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 78, 'B1', 9, 'sent', NULL, 'Dann feiern wir drinnen. Es wird auf jeden Fall lustig!', 'Then we celebrate inside. It will be fun in any case!', 'آنوقت داخل جشن می‌گیریم. به هر حال سرگرم‌کننده می‌شود!', NULL, NULL FROM lessons WHERE day = 78;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 0, 'received', 'Hast du schon eine neue Stelle gefunden?', NULL, 'Have you found a new job yet?', 'کار جدید پیدا کرده‌ای؟', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 1, 'sent', NULL, 'Noch nicht, aber ich habe mich bei drei Firmen beworben.', 'Not yet, but I''ve applied at three companies.', 'هنوز نه، ولی در سه شرکت درخواست داده‌ام.', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 2, 'received', 'Was für eine Stelle suchst du genau?', NULL, 'What kind of job are you looking for exactly?', 'دقیقاً دنبال چه شغلی هستی؟', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 3, 'sent', NULL, 'Ich suche etwas im Bereich Marketing oder Kommunikation.', 'I''m looking for something in marketing or communication.', 'دنبال چیزی در حوزه بازاریابی یا ارتباطات می‌گردم.', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 4, 'received', 'Hast du deinen Lebenslauf aktualisiert?', NULL, 'Have you updated your resume?', 'رزومه‌ات را به‌روز کرده‌ای؟', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 5, 'sent', NULL, 'Ja, ich habe ihn letzte Woche komplett überarbeitet.', 'Yes, I completely revised it last week.', 'بله، هفته پیش کاملاً بازنویسی کردم.', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 6, 'received', 'Hast du auch ein Anschreiben geschrieben?', NULL, 'Have you also written a cover letter?', 'نامه‌ی همراه هم نوشته‌ای؟', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 7, 'sent', NULL, 'Ja, für jede Firma ein individuelles Anschreiben.', 'Yes, an individual cover letter for each company.', 'بله، برای هر شرکت یک نامه جداگانه.', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 8, 'received', 'Das ist wichtig. Wann hast du das Vorstellungsgespräch?', NULL, 'That''s important. When do you have the interview?', 'مهمه. کی مصاحبه داری؟', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 79, 'B1', 9, 'sent', NULL, 'Am Mittwoch um zehn Uhr. Ich bin ein bisschen nervös.', 'On Wednesday at ten o''clock. I''m a little nervous.', 'چهارشنبه ساعت ده. کمی استرس دارم.', NULL, NULL FROM lessons WHERE day = 79;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 0, 'received', 'Erzähl mir von deiner Wohnung!', NULL, 'Tell me about your apartment!', 'از آپارتمانت بگو!', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 1, 'sent', NULL, 'Ich habe eine kleine Wohnung mit zwei Zimmern.', 'I have a small apartment with two rooms.', 'یک آپارتمان کوچک دو اتاقه دارم.', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 2, 'received', 'Gibt es einen Balkon?', NULL, 'Is there a balcony?', 'بالکن دارد؟', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 3, 'sent', NULL, 'Ja, es gibt einen kleinen Balkon mit Blick auf den Park.', 'Yes, there is a small balcony with a view of the park.', 'بله، یک بالکن کوچک با نمای پارک دارد.', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 4, 'received', 'Das klingt schön! Und wie ist die Küche?', NULL, 'That sounds nice! And how is the kitchen?', 'قشنگ به نظر می‌رسد! آشپزخانه چطوره؟', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 5, 'sent', NULL, 'Die Küche ist neu und hell. Es gibt einen großen Kühlschrank.', 'The kitchen is new and bright. There is a big refrigerator.', 'آشپزخانه نو و روشن است. یک یخچال بزرگ دارد.', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 6, 'received', 'Hast du auch eine Waschmaschine?', NULL, 'Do you also have a washing machine?', 'ماشین لباسشویی هم داری؟', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 7, 'sent', NULL, 'Ja, die steht im Badezimmer.', 'Yes, it''s in the bathroom.', 'بله، در حمام است.', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 8, 'received', 'Wie hoch ist die Miete?', NULL, 'How high is the rent?', 'اجاره چقدر است؟', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 80, 'A2', 9, 'sent', NULL, 'Ich bezahle fünfhundert Euro pro Monat inklusive Nebenkosten.', 'I pay five hundred euros per month including utilities.', 'ماهی پانصد یورو با هزینه‌های جانبی پرداخت می‌کنم.', NULL, NULL FROM lessons WHERE day = 80;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 0, 'received', 'Wo bist du aufgewachsen?', NULL, 'Where did you grow up?', 'کجا بزرگ شده‌ای؟', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 1, 'sent', NULL, 'Ich bin in einer kleinen Stadt aufgewachsen, aber als Kind wollte ich immer in einer großen Stadt leben.', 'I grew up in a small town, but as a child I always wanted to live in a big city.', 'در یک شهر کوچک بزرگ شدم، ولی وقتی بچه بودم همیشه می‌خواستم در شهر بزرگ زندگی کنم.', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 2, 'received', 'Hattest du viele Freunde?', NULL, 'Did you have many friends?', 'دوستان زیادی داشتی؟', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 3, 'sent', NULL, 'Ja, wir spielten jeden Tag zusammen im Park.', 'Yes, we played together in the park every day.', 'بله، هر روز با هم در پارک بازی می‌کردیم.', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 4, 'received', 'Was war dein Lieblingsspiel?', NULL, 'What was your favorite game?', 'بازی مورد علاقه‌ات چه بود؟', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 5, 'sent', NULL, 'Als ich klein war, spielte ich am liebsten Fußball.', 'When I was small, I liked playing football the most.', 'وقتی کوچک بودم، بیشتر از همه فوتبال بازی می‌کردم.', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 6, 'received', 'Hast du Geschwister?', NULL, 'Do you have siblings?', 'خواهر و برادر داری؟', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 7, 'sent', NULL, 'Ja, ich habe eine ältere Schwester. Sie half mir immer bei den Hausaufgaben.', 'Yes, I have an older sister. She always helped me with homework.', 'بله، یک خواهر بزرگ‌تر دارم. همیشه در تکالیف کمکم می‌کرد.', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 8, 'received', 'Das ist schön. Vermisst du deine Heimatstadt?', NULL, 'That''s nice. Do you miss your hometown?', 'قشنگه. دلت برای شهرت تنگ می‌شود؟', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 81, 'B1', 9, 'sent', NULL, 'Manchmal, besonders als ich hierher gezogen bin.', 'Sometimes, especially when I moved here.', 'گاهی اوقات، مخصوصاً وقتی به اینجا نقل مکان کردم.', NULL, NULL FROM lessons WHERE day = 81;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 0, 'received', 'Kaufst du oft im Internet ein?', NULL, 'Do you often shop on the internet?', 'زیاد اینترنتی خرید می‌کنی؟', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 1, 'sent', NULL, 'Ja, es ist einfacher, online einzukaufen.', 'Yes, it''s easier to shop online.', 'بله، خرید آنلاین راحت‌تر است.', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 2, 'received', 'Was hast du zuletzt bestellt?', NULL, 'What did you order last?', 'آخرین بار چه سفارش دادی؟', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 3, 'sent', NULL, 'Ich habe neue Schuhe bestellt, aber sie passen nicht.', 'I ordered new shoes, but they don''t fit.', 'کفش جدید سفارش دادم، ولی اندازه نیست.', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 4, 'received', 'Kannst du sie zurückschicken?', NULL, 'Can you send them back?', 'می‌توانی پسشان بفرستی؟', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 5, 'sent', NULL, 'Ja, ich habe dreißig Tage Zeit, um sie zurückzugeben.', 'Yes, I have thirty days to return them.', 'بله، سی روز فرصت دارم برای برگرداندنشان.', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 6, 'received', 'Das ist praktisch. Ist der Versand kostenlos?', NULL, 'That''s practical. Is shipping free?', 'عملی‌ه. ارسال رایگان است؟', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 7, 'sent', NULL, 'Ab fünfzig Euro ist der Versand kostenlos.', 'From fifty euros shipping is free.', 'از پنجاه یورو به بالا ارسال رایگان است.', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 8, 'received', 'Bezahlst du mit Kreditkarte?', NULL, 'Do you pay by credit card?', 'با کارت اعتباری پرداخت می‌کنی؟', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 82, 'A2', 9, 'sent', NULL, 'Nein, ich bevorzuge es, per Überweisung zu bezahlen.', 'No, I prefer to pay by bank transfer.', 'نه، ترجیح می‌دهم با انتقال بانکی پرداخت کنم.', NULL, NULL FROM lessons WHERE day = 82;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 0, 'received', 'Guten Tag! Haben Sie einen Termin?', NULL, 'Good day! Do you have an appointment?', 'روز بخیر! وقت قبلی دارید؟', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 1, 'sent', NULL, 'Ja, um vierzehn Uhr. Mein Name ist Mina.', 'Yes, at two o''clock. My name is Mina.', 'بله، ساعت دو. اسمم مینا است.', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 2, 'received', 'Was möchten Sie heute machen lassen?', NULL, 'What would you like to have done today?', 'امروز چه کاری می‌خواهید انجام دهید؟', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 3, 'sent', NULL, 'Ich möchte die Haare kürzer schneiden lassen.', 'I would like to have my hair cut shorter.', 'می‌خواهم موهایم را کوتاه‌تر کنم.', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 4, 'received', 'Wie kurz? Soll ich nur die Spitzen schneiden?', NULL, 'How short? Should I just trim the ends?', 'چقدر کوتاه؟ فقط نوکشان را بزنم؟', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 5, 'sent', NULL, 'Nein, bitte etwa fünf Zentimeter kürzer.', 'No, please about five centimeters shorter.', 'نه، لطفاً حدود پنج سانتی‌متر کوتاه‌تر.', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 6, 'received', 'Möchten Sie auch die Haare waschen?', NULL, 'Would you also like your hair washed?', 'می‌خواهید موها را هم بشویم؟', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 7, 'sent', NULL, 'Ja, bitte. Und föhnen Sie sie auch.', 'Yes, please. And blow-dry them too.', 'بله، لطفاً. و سشوار هم بکشید.', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 8, 'received', 'Das sieht sehr gut aus! Gefällt es Ihnen?', NULL, 'That looks very good! Do you like it?', 'خیلی خوب شده! خوشتان آمد؟', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 83, 'A2', 9, 'sent', NULL, 'Ja, sehr schön! Was muss ich bezahlen?', 'Yes, very nice! What do I have to pay?', 'بله، خیلی قشنگ شده! چقدر باید بپردازم؟', NULL, NULL FROM lessons WHERE day = 83;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 0, 'received', 'Hast du den neuen Film von diesem deutschen Regisseur gesehen?', NULL, 'Have you seen the new film by this German director?', 'فیلم جدید آن کارگردان آلمانی را دیده‌ای؟', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 1, 'sent', NULL, 'Ja, ich finde, dass der Film sehr spannend war.', 'Yes, I think that the film was very exciting.', 'بله، فکر می‌کنم فیلم خیلی هیجان‌انگیز بود.', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 2, 'received', 'Worum ging es in dem Film?', NULL, 'What was the film about?', 'فیلم درباره چه بود؟', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 3, 'sent', NULL, 'Es ging um eine Familie, die nach Deutschland ausgewandert ist.', 'It was about a family that emigrated to Germany.', 'درباره خانواده‌ای بود که به آلمان مهاجرت کرده بود.', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 4, 'received', 'Ich habe gelesen, dass die Schauspieler sehr gut waren.', NULL, 'I read that the actors were very good.', 'خوانده‌ام که بازیگران خیلی خوب بودند.', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 5, 'sent', NULL, 'Stimmt, besonders die Hauptdarstellerin war großartig.', 'True, especially the lead actress was magnificent.', 'درسته، مخصوصاً بازیگر اصلی زن فوق‌العاده بود.', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 6, 'received', 'Glaubst du, dass er einen Preis gewinnen wird?', NULL, 'Do you think that it will win a prize?', 'فکر می‌کنی جایزه‌ای بگیرد؟', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 7, 'sent', NULL, 'Ich bin mir sicher, dass er nominiert wird.', 'I''m sure that it will be nominated.', 'مطمئنم که نامزد خواهد شد.', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 8, 'received', 'Sollen wir nächste Woche zusammen ins Kino gehen?', NULL, 'Should we go to the cinema together next week?', 'هفته بعد با هم بریم سینما؟', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 84, 'B1', 9, 'sent', NULL, 'Gerne! Ich schlage vor, dass wir den Freitagabend nehmen.', 'Gladly! I suggest that we take Friday evening.', 'با کمال میل! پیشنهاد می‌کنم جمعه شب برویم.', NULL, NULL FROM lessons WHERE day = 84;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 0, 'received', 'In Deutschland muss man den Müll trennen.', NULL, 'In Germany you have to separate the trash.', 'در آلمان باید زباله‌ها را جدا کرد.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 1, 'sent', NULL, 'Ja, ich weiß. Aber ich bin mir nicht sicher, wie man das richtig macht.', 'Yes, I know. But I''m not sure how to do it correctly.', 'بله، می‌دانم. ولی مطمئن نیستم چطور درست انجامش بدهم.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 2, 'received', 'Papier kommt in die blaue Tonne und Plastik in die gelbe.', NULL, 'Paper goes in the blue bin and plastic in the yellow.', 'کاغذ در سطل آبی و پلاستیک در سطل زرد.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 3, 'sent', NULL, 'Und wohin bringt man Glasflaschen?', 'And where does one bring glass bottles?', 'و شیشه‌ها را کجا می‌برند؟', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 4, 'received', 'Glas bringt man zum Glascontainer. Es gibt verschiedene Farben.', NULL, 'Glass you bring to the glass container. There are different colors.', 'شیشه را به محل جمع‌آوری شیشه می‌برند. رنگ‌های مختلفی دارد.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 5, 'sent', NULL, 'Man kann auch Pfandflaschen im Supermarkt zurückgeben, oder?', 'You can also return deposit bottles at the supermarket, right?', 'بطری‌های سپرده‌دار را هم می‌شود در سوپرمارکت پس داد، نه؟', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 6, 'received', 'Genau! Dafür bekommt man fünfundzwanzig Cent pro Flasche.', NULL, 'Exactly! For that you get twenty-five cents per bottle.', 'دقیقاً! بابتش بیست و پنج سنت در هر بطری می‌گیرید.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 7, 'sent', NULL, 'Das finde ich gut. So schützt man die Umwelt.', 'I think that''s good. That''s how you protect the environment.', 'به نظرم خوبه. اینطوری از محیط زیست محافظت می‌شود.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 8, 'received', 'Wenn alle mitmachen, kann man viel verändern.', NULL, 'If everyone participates, you can change a lot.', 'اگر همه مشارکت کنند، می‌شود خیلی چیزها را تغییر داد.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 85, 'B1', 9, 'sent', NULL, 'Da hast du recht. Ich werde besser aufpassen.', 'You''re right about that. I''ll pay better attention.', 'حق با توست. بیشتر دقت خواهم کرد.', NULL, NULL FROM lessons WHERE day = 85;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 0, 'received', 'Wie lange lernst du schon Deutsch?', NULL, 'How long have you been learning German?', 'چه مدت است که آلمانی یاد می‌گیری؟', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 1, 'sent', NULL, 'Seit sechs Monaten. Ich lerne gern mit Apps.', 'For six months. I like learning with apps.', 'شش ماه است. با اپلیکیشن یاد گرفتن را دوست دارم.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 2, 'received', 'Lernst du lieber allein oder in einer Gruppe?', NULL, 'Do you prefer learning alone or in a group?', 'ترجیح می‌دهی تنها یاد بگیری یا در گروه؟', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 3, 'sent', NULL, 'Ich lerne lieber in einer kleinen Gruppe.', 'I prefer learning in a small group.', 'ترجیح می‌دهم در یک گروه کوچک یاد بگیرم.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 4, 'received', 'Was findest du am schwierigsten?', NULL, 'What do you find most difficult?', 'چه چیزی را از همه سخت‌تر می‌دانی؟', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 5, 'sent', NULL, 'Am schwierigsten finde ich die Artikel: der, die, das.', 'I find the articles most difficult: der, die, das.', 'حرف تعریف‌ها را از همه سخت‌تر می‌دانم: der, die, das.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 6, 'received', 'Ja, das ist für viele Lernende schwer.', NULL, 'Yes, that''s difficult for many learners.', 'بله، برای خیلی از زبان‌آموزان سخت است.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 7, 'sent', NULL, 'Am liebsten höre ich deutsche Podcasts.', 'I like listening to German podcasts the most.', 'بیشتر از همه دوست دارم پادکست‌های آلمانی گوش بدهم.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 8, 'received', 'Das ist eine gute Methode für das Hörverständnis.', NULL, 'That''s a good method for listening comprehension.', 'روش خوبی برای درک شنیداری است.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 86, 'A2', 9, 'sent', NULL, 'Ja, und ich sehe auch gern deutsche Filme mit Untertiteln.', 'Yes, and I also like watching German films with subtitles.', 'بله، و فیلم‌های آلمانی با زیرنویس هم دوست دارم ببینم.', NULL, NULL FROM lessons WHERE day = 86;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 0, 'received', 'Welche Jahreszeit magst du am liebsten?', NULL, 'Which season do you like the most?', 'کدام فصل را بیشتر دوست داری؟', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 1, 'sent', NULL, 'Ich mag den Frühling, wenn die Blumen blühen.', 'I like spring, when the flowers bloom.', 'بهار را دوست دارم، وقتی گل‌ها شکوفه می‌زنند.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 2, 'received', 'Im Sommer ist es oft sehr heiß in Deutschland.', NULL, 'In summer it''s often very hot in Germany.', 'در تابستان اغلب خیلی گرم است در آلمان.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 3, 'sent', NULL, 'Wenn es heiß ist, gehe ich gern schwimmen.', 'When it''s hot, I like to go swimming.', 'وقتی هوا گرم باشد، دوست دارم شنا بروم.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 4, 'received', 'Im Herbst werden die Blätter bunt.', NULL, 'In autumn the leaves become colorful.', 'در پاییز برگ‌ها رنگارنگ می‌شوند.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 5, 'sent', NULL, 'Ja, aber es regnet auch oft.', 'Yes, but it also rains often.', 'بله، ولی باران هم زیاد می‌بارد.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 6, 'received', 'Und im Winter schneit es manchmal.', NULL, 'And in winter it sometimes snows.', 'و در زمستان گاهی برف می‌بارد.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 7, 'sent', NULL, 'Wenn es schneit, mache ich gern einen Spaziergang.', 'When it snows, I like to take a walk.', 'وقتی برف می‌بارد، دوست دارم پیاده‌روی کنم.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 8, 'received', 'Heute sind es fünfzehn Grad und bewölkt.', NULL, 'Today it''s fifteen degrees and cloudy.', 'امروز پانزده درجه و ابری است.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 87, 'A2', 9, 'sent', NULL, 'Dann brauche ich eine Jacke, wenn ich rausgehe.', 'Then I need a jacket when I go out.', 'پس وقتی بیرون می‌روم به کاپشن نیاز دارم.', NULL, NULL FROM lessons WHERE day = 87;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 0, 'received', 'Kennst du deine Nachbarn?', NULL, 'Do you know your neighbors?', 'همسایه‌هایت را می‌شناسی؟', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 1, 'sent', NULL, 'Ja, die Familie, die neben mir wohnt, ist sehr nett.', 'Yes, the family that lives next to me is very nice.', 'بله، خانواده‌ای که کنارم زندگی می‌کنند خیلی مهربان هستند.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 2, 'received', 'Hast du einen Nachbarn, der laut ist?', NULL, 'Do you have a neighbor who is loud?', 'همسایه‌ای داری که سروصدا کند؟', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 3, 'sent', NULL, 'Der Mann, der über mir wohnt, hört manchmal abends laute Musik.', 'The man who lives above me sometimes listens to loud music in the evening.', 'مردی که بالای من زندگی می‌کند گاهی شب‌ها موسیقی بلند گوش می‌دهد.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 4, 'received', 'Hast du schon mit ihm gesprochen?', NULL, 'Have you already spoken with him?', 'با او صحبت کرده‌ای؟', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 5, 'sent', NULL, 'Ja, er hat sich entschuldigt. Das Problem, das wir hatten, ist jetzt gelöst.', 'Yes, he apologized. The problem that we had is now solved.', 'بله، عذرخواهی کرد. مشکلی که داشتیم حالا حل شده.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 6, 'received', 'Das ist gut. In meinem Haus gibt es eine Frau, die immer Kuchen backt.', NULL, 'That''s good. In my building there''s a woman who always bakes cakes.', 'خوبه. در ساختمان من خانمی هست که همیشه کیک می‌پزد.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 7, 'sent', NULL, 'Das klingt toll! Die Nachbarschaft, in der ich wohne, ist ruhig und freundlich.', 'That sounds great! The neighborhood where I live is quiet and friendly.', 'عالی به نظر می‌رسد! محله‌ای که من در آن زندگی می‌کنم آرام و دوستانه است.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 8, 'received', 'Es ist wichtig, gute Nachbarn zu haben.', NULL, 'It''s important to have good neighbors.', 'مهمه که همسایه‌های خوبی داشته باشیم.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 88, 'B1', 9, 'sent', NULL, 'Da stimme ich dir zu. Gute Nachbarn machen das Leben schöner.', 'I agree with you. Good neighbors make life nicer.', 'با تو موافقم. همسایه‌های خوب زندگی را زیباتر می‌کنند.', NULL, NULL FROM lessons WHERE day = 88;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 0, 'received', 'Hast du ein Haustier?', NULL, 'Do you have a pet?', 'حیوان خانگی داری؟', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 1, 'sent', NULL, 'Ja, ich habe eine Katze. Sie heißt Luna.', 'Yes, I have a cat. Her name is Luna.', 'بله، یک گربه دارم. اسمش لونا است.', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 2, 'received', 'Wie alt ist deine Katze?', NULL, 'How old is your cat?', 'گربه‌ات چند ساله است؟', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 3, 'sent', NULL, 'Meine Katze ist drei Jahre alt.', 'My cat is three years old.', 'گربه‌ام سه ساله است.', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 4, 'received', 'Ich habe einen Hund. Sein Name ist Max.', NULL, 'I have a dog. His name is Max.', 'من یک سگ دارم. اسمش مکس است.', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 5, 'sent', NULL, 'Wie süß! Gehst du jeden Tag mit ihm spazieren?', 'How cute! Do you walk him every day?', 'چه بامزه! هر روز باهاش پیاده‌روی می‌کنی؟', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 6, 'received', 'Ja, unser Hund braucht viel Bewegung.', NULL, 'Yes, our dog needs a lot of exercise.', 'بله، سگ ما به حرکت زیاد نیاز دارد.', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 7, 'sent', NULL, 'Meine Katze schläft den ganzen Tag auf ihrem Kissen.', 'My cat sleeps the whole day on her pillow.', 'گربه‌ام تمام روز روی بالشتش می‌خوابد.', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 8, 'received', 'Möchtest du auch einen Hund haben?', NULL, 'Would you also like to have a dog?', 'دوست داری سگ هم داشته باشی؟', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 89, 'A2', 9, 'sent', NULL, 'Vielleicht später. Jetzt ist meine Wohnung zu klein für einen Hund.', 'Maybe later. Now my apartment is too small for a dog.', 'شاید بعداً. الان آپارتمانم برای سگ خیلی کوچک است.', NULL, NULL FROM lessons WHERE day = 89;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 0, 'received', 'Warst du schon mal auf einem deutschen Volksfest?', NULL, 'Have you ever been to a German folk festival?', 'تا حالا در یک جشن سنتی آلمانی بوده‌ای؟', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 1, 'sent', NULL, 'Nein, noch nicht. Aber ich habe gehört, dass das Oktoberfest sehr bekannt ist.', 'No, not yet. But I''ve heard that Oktoberfest is very famous.', 'نه، هنوز نه. ولی شنیده‌ام که اکتبرفست خیلی معروف است.', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 2, 'received', 'Ja, es wird jedes Jahr in München gefeiert.', NULL, 'Yes, it''s celebrated every year in Munich.', 'بله، هر سال در مونیخ جشن گرفته می‌شود.', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 3, 'sent', NULL, 'Wann findet es statt?', 'When does it take place?', 'کی برگزار می‌شود؟', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 4, 'received', 'Es wird von Ende September bis Anfang Oktober gefeiert.', NULL, 'It''s celebrated from end of September to beginning of October.', 'از آخر سپتامبر تا اول اکتبر جشن گرفته می‌شود.', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 5, 'sent', NULL, 'Was wird dort gemacht?', 'What is done there?', 'آنجا چه کار می‌شود؟', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 6, 'received', 'Es wird viel gegessen, getrunken und getanzt.', NULL, 'A lot of eating, drinking, and dancing is done.', 'خیلی خورده، نوشیده و رقصیده می‌شود.', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 7, 'sent', NULL, 'Auch Weihnachtsmärkte sind sehr schön, oder?', 'Christmas markets are also very nice, right?', 'بازارهای کریسمس هم خیلی قشنگ هستند، نه؟', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 8, 'received', 'Ja, im Dezember werden überall Weihnachtsmärkte organisiert.', NULL, 'Yes, in December Christmas markets are organized everywhere.', 'بله، در دسامبر همه جا بازارهای کریسمس برگزار می‌شوند.', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 90, 'B1', 9, 'sent', NULL, 'Dort wird auch Glühwein verkauft. Den möchte ich probieren!', 'Mulled wine is also sold there. I want to try that!', 'آنجا شراب داغ هم فروخته می‌شود. می‌خواهم امتحانش کنم!', NULL, NULL FROM lessons WHERE day = 90;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 0, 'received', 'Ich habe Probleme mit meinem Vermieter. Was sollte ich tun?', NULL, 'I have problems with my landlord. What should I do?', 'با صاحبخانه‌ام مشکل دارم. چه کار کنم؟', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 1, 'sent', NULL, 'Du solltest zuerst ruhig mit ihm sprechen.', 'You should first speak calmly with him.', 'اول باید با آرامش باهاش صحبت کنی.', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 2, 'received', 'Ich habe es versucht, aber er hört nicht zu.', NULL, 'I tried, but he doesn''t listen.', 'امتحان کردم، ولی گوش نمی‌دهد.', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 3, 'sent', NULL, 'An deiner Stelle würde ich alles schriftlich dokumentieren.', 'In your place I would document everything in writing.', 'جای تو بودم همه چیز را کتبی مستند می‌کردم.', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 4, 'received', 'Das ist ein guter Rat. Sollte ich auch zum Mieterverein gehen?', NULL, 'That''s good advice. Should I also go to the tenants'' association?', 'نصیحت خوبی‌ه. به انجمن مستأجران هم بروم؟', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 5, 'sent', NULL, 'Ja, das würde ich dir empfehlen. Sie können dir rechtlich helfen.', 'Yes, I would recommend that to you. They can help you legally.', 'بله، توصیه‌ام همین است. می‌توانند از نظر حقوقی کمکت کنند.', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 6, 'received', 'Was würdest du machen, wenn die Heizung nicht funktioniert?', NULL, 'What would you do if the heating doesn''t work?', 'اگر بخاری کار نکند چه می‌کردی؟', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 7, 'sent', NULL, 'Ich würde sofort den Vermieter informieren und eine Frist setzen.', 'I would immediately inform the landlord and set a deadline.', 'فوراً به صاحبخانه اطلاع می‌دادم و مهلت تعیین می‌کردم.', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 8, 'received', 'Du kennst dich gut aus mit solchen Themen!', NULL, 'You know your stuff about such topics!', 'خوب از این موضوعات سر در می‌آوری!', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 91, 'B1', 9, 'sent', NULL, 'Ich habe selbst ähnliche Erfahrungen gemacht.', 'I''ve had similar experiences myself.', 'خودم تجربه‌های مشابهی داشته‌ام.', NULL, NULL FROM lessons WHERE day = 91;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 0, 'received', 'Wohin fährst du in den Sommerferien?', NULL, 'Where are you going for summer vacation?', 'تعطیلات تابستان کجا می‌روی؟', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 1, 'sent', NULL, 'Ich werde nach Österreich fahren.', 'I will go to Austria.', 'به اتریش خواهم رفت.', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 2, 'received', 'Schön! Wirst du mit dem Zug oder dem Auto fahren?', NULL, 'Nice! Will you go by train or car?', 'عالی! با قطار می‌روی یا ماشین؟', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 3, 'sent', NULL, 'Ich werde den Zug nehmen. Es ist bequemer.', 'I will take the train. It''s more comfortable.', 'قطار می‌گیرم. راحت‌تر است.', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 4, 'received', 'Wie lange wirst du dort bleiben?', NULL, 'How long will you stay there?', 'چه مدت آنجا می‌مانی؟', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 5, 'sent', NULL, 'Ich werde eine Woche in Wien bleiben.', 'I will stay one week in Vienna.', 'یک هفته در وین می‌مانم.', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 6, 'received', 'Hast du schon ein Hotel gebucht?', NULL, 'Have you already booked a hotel?', 'هتل رزرو کرده‌ای؟', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 7, 'sent', NULL, 'Ja, ein kleines Hotel in der Stadtmitte.', 'Yes, a small hotel in the city center.', 'بله، یک هتل کوچک در مرکز شهر.', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 8, 'received', 'Was wirst du dort machen?', NULL, 'What will you do there?', 'آنجا چه کار خواهی کرد؟', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 92, 'A2', 9, 'sent', NULL, 'Ich werde Museen besuchen und die Stadt erkunden.', 'I will visit museums and explore the city.', 'از موزه‌ها بازدید می‌کنم و شهر را کشف می‌کنم.', NULL, NULL FROM lessons WHERE day = 92;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 0, 'received', 'Hallo, hier ist die Praxis von Dr. Müller. Was kann ich für Sie tun?', NULL, 'Hello, this is Dr. Müller''s office. What can I do for you?', 'سلام، مطب دکتر مولر. چه کمکی می‌توانم بکنم؟', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 1, 'sent', NULL, 'Guten Tag, ich möchte gern einen Termin machen.', 'Good day, I would like to make an appointment.', 'روز بخیر، می‌خواهم یک وقت بگیرم.', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 2, 'received', 'Wann passt es Ihnen?', NULL, 'When suits you?', 'کی برایتان مناسب است؟', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 3, 'sent', NULL, 'Könnten Sie mir einen Termin am Donnerstag geben?', 'Could you give me an appointment on Thursday?', 'می‌توانید پنجشنبه وقت بدهید؟', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 4, 'received', 'Am Donnerstag haben wir um elf Uhr einen freien Termin.', NULL, 'On Thursday we have a free slot at eleven o''clock.', 'پنجشنبه ساعت یازده وقت خالی داریم.', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 5, 'sent', NULL, 'Das passt gut. Können Sie bitte meinen Namen notieren?', 'That works well. Can you please note my name?', 'خوبه. می‌توانید لطفاً اسمم را یادداشت کنید؟', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 6, 'received', 'Natürlich, wie ist Ihr Name?', NULL, 'Of course, what is your name?', 'البته، اسمتان چیست؟', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 7, 'sent', NULL, 'Mein Name ist Ahmadi. A-H-M-A-D-I.', 'My name is Ahmadi. A-H-M-A-D-I.', 'اسمم احمدی است. A-H-M-A-D-I.', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 8, 'received', 'Alles klar, Herr Ahmadi. Donnerstag um elf Uhr.', NULL, 'All clear, Mr. Ahmadi. Thursday at eleven o''clock.', 'بسیار خب، آقای احمدی. پنجشنبه ساعت یازده.', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 93, 'A2', 9, 'sent', NULL, 'Vielen Dank! Auf Wiederhören.', 'Thank you very much! Goodbye (on phone).', 'خیلی ممنون! خداحافظ.', NULL, NULL FROM lessons WHERE day = 93;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 0, 'received', 'Treibst du regelmäßig Sport?', NULL, 'Do you exercise regularly?', 'مرتب ورزش می‌کنی؟', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 1, 'sent', NULL, 'Ja, ich spiele seit zwei Jahren Tennis.', 'Yes, I''ve been playing tennis for two years.', 'بله، دو سال است تنیس بازی می‌کنم.', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 2, 'received', 'Das ist toll! Hast du auch andere Hobbys?', NULL, 'That''s great! Do you also have other hobbies?', 'عالیه! سرگرمی‌های دیگری هم داری؟', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 3, 'sent', NULL, 'Seit letztem Jahr lerne ich Gitarre spielen.', 'Since last year I''ve been learning to play guitar.', 'از سال گذشته دارم گیتار یاد می‌گیرم.', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 4, 'received', 'Wie oft übst du Gitarre?', NULL, 'How often do you practice guitar?', 'چند وقت یکبار گیتار تمرین می‌کنی؟', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 5, 'sent', NULL, 'Ich übe jeden Abend eine halbe Stunde.', 'I practice every evening for half an hour.', 'هر شب نیم ساعت تمرین می‌کنم.', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 6, 'received', 'Seit wann interessierst du dich für Musik?', NULL, 'Since when have you been interested in music?', 'از کی به موسیقی علاقه‌مند شده‌ای؟', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 7, 'sent', NULL, 'Seit meiner Kindheit. Mein Vater hat auch Gitarre gespielt.', 'Since my childhood. My father also played guitar.', 'از کودکی. پدرم هم گیتار می‌زد.', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 8, 'received', 'Spielst du auch in einer Band?', NULL, 'Do you also play in a band?', 'در گروه موسیقی هم می‌زنی؟', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 94, 'B1', 9, 'sent', NULL, 'Noch nicht, aber seit ein paar Wochen suche ich eine Gruppe.', 'Not yet, but for a few weeks I''ve been looking for a group.', 'هنوز نه، ولی چند هفته‌ای هست دنبال یک گروه می‌گردم.', NULL, NULL FROM lessons WHERE day = 94;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 0, 'received', 'Guten Abend! Haben Sie reserviert?', NULL, 'Good evening! Have you reserved?', 'عصر بخیر! رزرو کرده‌اید؟', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 1, 'sent', NULL, 'Ja, ich wollte fragen, ob der Tisch am Fenster frei ist.', 'Yes, I wanted to ask if the table by the window is free.', 'بله، می‌خواستم بپرسم آیا میز کنار پنجره خالی است.', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 2, 'received', 'Natürlich. Kann ich Ihnen die Speisekarte bringen?', NULL, 'Of course. Can I bring you the menu?', 'البته. منو بیاورم؟', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 3, 'sent', NULL, 'Ja, bitte. Können Sie mir sagen, was Sie heute empfehlen?', 'Yes, please. Can you tell me what you recommend today?', 'بله، لطفاً. می‌توانید بگویید امروز چه چیزی پیشنهاد می‌کنید؟', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 4, 'received', 'Ich empfehle das Wiener Schnitzel. Es ist unser Spezialität.', NULL, 'I recommend the Wiener Schnitzel. It''s our specialty.', 'شنیتسل وینی را پیشنهاد می‌کنم. غذای مخصوص ما است.', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 5, 'sent', NULL, 'Ich wüsste gern, ob es auch vegetarische Gerichte gibt.', 'I would like to know if there are also vegetarian dishes.', 'می‌خواستم بدانم آیا غذاهای گیاهی هم دارید.', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 6, 'received', 'Ja, wir haben Gemüselasagne und einen großen Salat.', NULL, 'Yes, we have vegetable lasagna and a large salad.', 'بله، لازانیای سبزیجات و سالاد بزرگ داریم.', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 7, 'sent', NULL, 'Können Sie mir sagen, wie lange die Zubereitung dauert?', 'Can you tell me how long the preparation takes?', 'می‌توانید بگویید آماده شدنش چقدر طول می‌کشد؟', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'A2', 8, 'received', 'Ungefähr zwanzig Minuten.', NULL, 'About twenty minutes.', 'حدود بیست دقیقه.', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 95, 'B1', 9, 'sent', NULL, 'Perfekt. Ich hätte gern die Gemüselasagne und ein Wasser, bitte.', 'Perfect. I would like the vegetable lasagna and a water, please.', 'عالی. لطفاً لازانیای سبزیجات و یک آب.', NULL, NULL FROM lessons WHERE day = 95;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 0, 'received', 'Wie bleibst du gesund?', NULL, 'How do you stay healthy?', 'چطور سالم می‌مانی؟', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 1, 'sent', NULL, 'Ich versuche, regelmäßig Sport zu treiben, um fit zu bleiben.', 'I try to exercise regularly to stay fit.', 'سعی می‌کنم مرتب ورزش کنم تا سرحال بمانم.', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 2, 'received', 'Achtest du auch auf deine Ernährung?', NULL, 'Do you also pay attention to your diet?', 'به تغذیه‌ات هم توجه می‌کنی؟', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 3, 'sent', NULL, 'Ja, ich esse viel Gemüse und Obst, um genug Vitamine zu bekommen.', 'Yes, I eat a lot of vegetables and fruit to get enough vitamins.', 'بله، زیاد سبزیجات و میوه می‌خورم تا ویتامین کافی بگیرم.', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 4, 'received', 'Was machst du, um Stress abzubauen?', NULL, 'What do you do to reduce stress?', 'برای کاهش استرس چه می‌کنی؟', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 5, 'sent', NULL, 'Ich mache Yoga und meditiere, um mich zu entspannen.', 'I do yoga and meditate to relax.', 'یوگا و مدیتیشن انجام می‌دهم تا آرام شوم.', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 6, 'received', 'Schläfst du genug?', NULL, 'Do you sleep enough?', 'خوابت کافی‌ه؟', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 7, 'sent', NULL, 'Ich versuche, acht Stunden zu schlafen, um erholt aufzuwachen.', 'I try to sleep eight hours to wake up rested.', 'سعی می‌کنم هشت ساعت بخوابم تا سرحال بیدار شوم.', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 8, 'received', 'Das ist wichtig. Gehst du auch regelmäßig zum Arzt?', NULL, 'That''s important. Do you also go to the doctor regularly?', 'مهمه. مرتب هم پیش دکتر می‌روی؟', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 96, 'B1', 9, 'sent', NULL, 'Ja, einmal im Jahr, um mich untersuchen zu lassen.', 'Yes, once a year to get examined.', 'بله، سالی یکبار برای معاینه.', NULL, NULL FROM lessons WHERE day = 96;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 0, 'received', 'Musst du oft E-Mails auf Deutsch schreiben?', NULL, 'Do you often have to write emails in German?', 'زیاد باید ایمیل آلمانی بنویسی؟', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 1, 'sent', NULL, 'Ja, für die Arbeit schreibe ich jeden Tag E-Mails.', 'Yes, for work I write emails every day.', 'بله، برای کار هر روز ایمیل می‌نویسم.', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 2, 'received', 'Weißt du, wie man eine formelle E-Mail beginnt?', NULL, 'Do you know how to start a formal email?', 'می‌دانی چطور یک ایمیل رسمی را شروع کنی؟', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 3, 'sent', NULL, 'Ja, man schreibt: Sehr geehrte Damen und Herren.', 'Yes, you write: Dear ladies and gentlemen.', 'بله، می‌نویسی: خانم‌ها و آقایان محترم.', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 4, 'received', 'Und wie beendet man eine formelle E-Mail?', NULL, 'And how do you end a formal email?', 'و چطور یک ایمیل رسمی را تمام می‌کنی؟', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 5, 'sent', NULL, 'Mit freundlichen Grüßen und dann der Name.', 'With kind regards and then the name.', 'با احترام و بعد اسم.', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 6, 'received', 'Und bei Freunden? Wie schreibst du da?', NULL, 'And with friends? How do you write then?', 'و به دوستان؟ چطور می‌نویسی؟', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 7, 'sent', NULL, 'Bei Freunden schreibe ich: Lieber Tom oder Liebe Anna.', 'With friends I write: Dear Tom or Dear Anna.', 'به دوستان می‌نویسم: تام عزیز یا آنا عزیز.', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 8, 'received', 'Und am Ende?', NULL, 'And at the end?', 'و آخرش؟', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 97, 'A2', 9, 'sent', NULL, 'Viele Grüße oder Liebe Grüße und mein Name.', 'Many greetings or love greetings and my name.', 'با مهر و بعد اسمم.', NULL, NULL FROM lessons WHERE day = 97;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 0, 'received', 'Gibt es in Deutschland besondere Regeln, die man beachten sollte?', NULL, 'Are there special rules in Germany that one should follow?', 'در آلمان قوانین خاصی وجود دارد که باید رعایت کرد؟', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 1, 'sent', NULL, 'Ja, man sollte zum Beispiel immer pünktlich sein.', 'Yes, for example you should always be punctual.', 'بله، مثلاً باید همیشه به موقع باشی.', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 2, 'received', 'Was passiert, wenn man sich verspätet?', NULL, 'What happens if you''re late?', 'اگر دیر برسی چه می‌شود؟', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 3, 'sent', NULL, 'Man sollte auf jeden Fall vorher anrufen und Bescheid sagen.', 'You should definitely call beforehand and let them know.', 'حتماً باید قبلش زنگ بزنی و خبر بدهی.', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 4, 'received', 'Stimmt es, dass man in Deutschland die Schuhe auszieht?', NULL, 'Is it true that in Germany you take off your shoes?', 'راست است که در آلمان کفش‌ها را درمی‌آورند؟', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 5, 'sent', NULL, 'Ja, wenn man jemanden zu Hause besucht, sollte man die Schuhe ausziehen.', 'Yes, when you visit someone at home, you should take off your shoes.', 'بله، وقتی به خانه کسی می‌روی باید کفش‌هایت را دربیاوری.', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 6, 'received', 'Und man sollte nicht am Sonntag den Rasen mähen, oder?', NULL, 'And you shouldn''t mow the lawn on Sunday, right?', 'و یکشنبه‌ها نباید چمن زد، درسته؟', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 7, 'sent', NULL, 'Genau, am Sonntag sollte man keinen Lärm machen. Das ist Ruhetag.', 'Exactly, on Sunday you shouldn''t make noise. That''s a rest day.', 'دقیقاً، یکشنبه نباید سروصدا کرد. روز استراحت است.', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 8, 'received', 'Das ist sehr anders als in meinem Heimatland.', NULL, 'That''s very different from my home country.', 'خیلی فرق دارد با کشورم.', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 98, 'B1', 9, 'sent', NULL, 'Jedes Land hat seine eigenen Traditionen. Man gewöhnt sich daran.', 'Every country has its own traditions. You get used to it.', 'هر کشوری سنت‌های خودش را دارد. عادت می‌کنی.', NULL, NULL FROM lessons WHERE day = 98;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 0, 'received', 'Wie fühlst du dich mit deinem Deutsch nach diesen Lektionen?', NULL, 'How do you feel about your German after these lessons?', 'بعد از این درس‌ها حس چطوری درباره آلمانیت داری؟', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 1, 'sent', NULL, 'Ich bin froh, dass ich so viel gelernt habe.', 'I''m glad that I''ve learned so much.', 'خوشحالم که این‌قدر یاد گرفته‌ام.', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 2, 'received', 'Was hat dir am meisten geholfen?', NULL, 'What helped you the most?', 'چه چیزی بیشتر از همه کمکت کرده؟', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 3, 'sent', NULL, 'Ich glaube, dass die Dialoge am hilfreichsten waren, weil sie sehr praktisch sind.', 'I believe that the dialogues were most helpful because they are very practical.', 'فکر می‌کنم مکالمه‌ها بیشتر از همه کمک‌کننده بودند، چون خیلی کاربردی هستند.', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 4, 'received', 'Kannst du jetzt besser im Alltag kommunizieren?', NULL, 'Can you communicate better in daily life now?', 'حالا می‌توانی بهتر در زندگی روزمره ارتباط برقرار کنی؟', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 5, 'sent', NULL, 'Ja, ich kann jetzt beim Arzt, im Restaurant und bei der Arbeit Deutsch sprechen.', 'Yes, I can now speak German at the doctor, in restaurants, and at work.', 'بله، حالا می‌توانم پیش دکتر، در رستوران و سر کار آلمانی صحبت کنم.', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 6, 'received', 'Das ist ein großer Fortschritt!', NULL, 'That''s great progress!', 'پیشرفت بزرگی است!', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 7, 'sent', NULL, 'Ja, weil ich jeden Tag geübt habe.', 'Yes, because I practiced every day.', 'بله، چون هر روز تمرین کرده‌ام.', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 8, 'received', 'Was möchtest du als Nächstes lernen?', NULL, 'What would you like to learn next?', 'بعد از این چه چیزی می‌خواهی یاد بگیری؟', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 99, 'B1', 9, 'sent', NULL, 'Ich möchte mein Hörverständnis verbessern und mehr Bücher auf Deutsch lesen.', 'I want to improve my listening comprehension and read more books in German.', 'می‌خواهم درک شنیداری‌ام را بهتر کنم و کتاب‌های بیشتری به آلمانی بخوانم.', NULL, NULL FROM lessons WHERE day = 99;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 0, 'received', 'Herzlichen Glückwunsch! Du hast alle hundert Lektionen geschafft!', NULL, 'Congratulations! You''ve completed all one hundred lessons!', 'تبریک! هر صد درس را تمام کردی!', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 1, 'sent', NULL, 'Danke! Ich bin sehr stolz auf mich.', 'Thank you! I''m very proud of myself.', 'ممنون! از خودم خیلی راضی‌ام.', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 2, 'received', 'Was sind deine Ziele für die Zukunft?', NULL, 'What are your goals for the future?', 'اهدافت برای آینده چیست؟', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 3, 'sent', NULL, 'Ich werde weiter Deutsch lernen und die B1-Prüfung machen.', 'I will continue learning German and take the B1 exam.', 'به یادگیری آلمانی ادامه می‌دهم و آزمون B1 می‌دهم.', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 4, 'received', 'Das ist ein tolles Ziel! Ich bin sicher, dass du es schaffst.', NULL, 'That''s a great goal! I''m sure you''ll make it.', 'هدف عالی‌ه! مطمئنم موفق می‌شوی.', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 5, 'sent', NULL, 'Wenn ich die Prüfung bestehe, werde ich mich um eine Stelle in Deutschland bewerben.', 'If I pass the exam, I will apply for a job in Germany.', 'اگر قبول شوم، در آلمان برای کار درخواست خواهم داد.', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 6, 'received', 'Würdest du wirklich nach Deutschland ziehen?', NULL, 'Would you really move to Germany?', 'واقعاً به آلمان نقل مکان می‌کنی؟', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 7, 'sent', NULL, 'Ja, das wäre mein Traum. Ich würde gern in München oder Berlin leben.', 'Yes, that would be my dream. I would like to live in Munich or Berlin.', 'بله، آرزویم همین است. دوست دارم در مونیخ یا برلین زندگی کنم.', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 8, 'received', 'Dann wünsche ich dir viel Erfolg auf deinem Weg!', NULL, 'Then I wish you much success on your way!', 'پس برایت آرزوی موفقیت می‌کنم در مسیرت!', NULL, NULL FROM lessons WHERE day = 100;
INSERT INTO sentences (lesson_id, day, difficulty, sentence_order, role, audio_text, target_text, translation, translation_fa, hint, hint_fa) SELECT id, 100, 'B1', 9, 'sent', NULL, 'Vielen Dank für alles! Dieses Abenteuer war erst der Anfang.', 'Thank you for everything! This adventure was just the beginning.', 'از همه چیز ممنونم! این ماجرا فقط شروع بود.', NULL, NULL FROM lessons WHERE day = 100;
